function positionDropdownInHost(drop,input,host,gap){
  if(!drop||!input)return;
  var h=host||input.parentElement;
  if(h&&window.getComputedStyle(h).position==='static')h.style.position='relative';
  var spacing=Number(gap)||3;
  var left=0;
  var top=0;
  var width=0;
  try{
    var ir=input.getBoundingClientRect();
    var hr=(h&&h.getBoundingClientRect)?h.getBoundingClientRect():null;
    if(hr){
      left=ir.left-hr.left;
      top=ir.bottom-hr.top+spacing;
      width=ir.width;
    }else{
      left=input.offsetLeft||0;
      top=(input.offsetTop||0)+(input.offsetHeight||0)+spacing;
      width=input.offsetWidth||Math.round(ir.width)||0;
    }
  }catch(_e){
    left=input.offsetLeft||0;
    top=(input.offsetTop||0)+(input.offsetHeight||0)+spacing;
    width=input.offsetWidth||0;
  }
  var hostW=h&&h.clientWidth?h.clientWidth:0;
  if(hostW>0){
    if(left<0)left=0;
    if(left>hostW)left=0;
    var maxW=Math.max(80,hostW-left-2);
    if(width>maxW)width=maxW;
    if(left+width>hostW)left=Math.max(0,hostW-width-2);
  }
  drop.style.position='absolute';
  drop.style.left=Math.round(left)+'px';
  drop.style.top=Math.round(top)+'px';
  if(width>0){
    var w=Math.round(width)+'px';
    drop.style.width=w;
    drop.style.minWidth=w;
    drop.style.maxWidth=w;
  }
}
