function animateDropdownOpen(el){
  if(!el||el.nodeType!==1)return;
  if(!el.classList||!el.classList.contains('tm-name-suggest-dropdown'))return;
  if(el.dataset.noOpenAnim==='1')return;
  var now=Date.now();
  var last=Number(el.dataset.tmAnimAt||0);
  if(now-last<140)return;
  el.dataset.tmAnimAt=String(now);
  el.classList.remove('tm-picker-anim-open');
  void el.offsetWidth;
  el.classList.add('tm-picker-anim-open');
}
function animatePickerOpen(el){
  if(!el||el.nodeType!==1)return;
  el.classList.remove('tm-picker-anim-open');
  void el.offsetWidth;
  el.classList.add('tm-picker-anim-open');
}
function animateDropdownClose(el,cb){
  if(!el||el.nodeType!==1){if(cb)cb();return;}
  el.style.pointerEvents='none';
  el.style.transformOrigin='top center';
  var done=false;
  function finish(){if(done)return;done=true;if(cb)cb();}
  try{
    var anim=el.animate(
      [{opacity:'1',transform:'translateY(0) scale(1)'},{opacity:'0',transform:'translateY(-6px) scale(.97)'}],
      {duration:150,easing:'cubic-bezier(.2,.8,.2,1)',fill:'forwards'}
    );
    anim.onfinish=finish;
    anim.oncancel=finish;
  }catch(e){finish();}
  setTimeout(finish,220);
}
function escapeHtml(v){return String(v||'').replace(/[&<>\"']/g,function(ch){return ch==='&'?'&amp;':ch==='<'?'&lt;':ch==='>'?'&gt;':ch==='\"'?'&quot;':'&#39;';});}
function formatPinnedInfoHtml(raw){
  const rawText=String(raw||'').replace(/\r/g,'');
  const compact=rawText.replace(/\s+/g,' ').trim();
  if(!compact)return '<span class="pin-empty">—</span>';
  let txt=rawText;
  txt=txt.replace(/\s*,\s*/g,', ');
  txt=txt.replace(/(\d+)\.(?=[A-Za-z\u0400-\u04FF])/g,'$1. ');
  const lines=txt.split('\n').map(function(x){
    return String(x||'').replace(/[ \t]+/g,' ').trim();
  }).filter(Boolean);
  const normalizedLines=lines.length?lines:[compact];
  return normalizedLines.map(function(line){
    return '<span class="pin-line">'+escapeHtml(line)+'</span>';
  }).join('');
}
function formatPartnerInfoHtml(raw){
  var rawText=String(raw||'').replace(/\r/g,'');
  var compact=rawText.replace(/\s+/g,' ').trim();
  if(!compact)return '<span class="partner-empty">—</span>';
  var lines=[];
  rawText.split('\n').forEach(function(chunk){
    String(chunk||'').split(/\s*;\s*/).forEach(function(part){
      var cleaned=String(part||'').replace(/[ \t]+/g,' ').trim();
      if(cleaned)lines.push(cleaned);
    });
  });
  if(!lines.length)lines=[compact];
  return lines.map(function(line){
    return '<span class="partner-line">'+escapeHtml(line)+'</span>';
  }).join('');
}
function normalizePendingCreatePhone(value){
  const digits=String(value||'').replace(/\D/g,'');
  if(!digits)return'';
  let normalized=digits;
  if(normalized.length===10)normalized=`7${normalized}`;
  if(normalized.length===11&&normalized.startsWith('8'))normalized=`7${normalized.slice(1)}`;
  if(normalized.length!==11||!normalized.startsWith('7'))return'';
  return `+${normalized}`;
}
function shouldUsePendingCreatePhone(){
  try{
    const ref=new URL(document.referrer||'',location.origin);
    if(!ref.pathname.includes('/customer-request/index'))return false;
    if(ref.searchParams.get('tm_open_all_numbers')!=='1')return false;
    const refPhone=normalizePendingCreatePhone(ref.searchParams.get('phone')||'');
    return !!refPhone;
  }catch(_e){return false;}
}
function takePendingCreatePhone(){
  let raw='';
  try{raw=String(sessionStorage.getItem(CREATE_PHONE_PENDING_KEY)||'');}catch(_e){return'';}
  if(!raw)return'';
  if(!shouldUsePendingCreatePhone())return'';
  let payload=null;
  try{payload=JSON.parse(raw);}catch(_e){payload={phone:raw};}
  const createdAt=Number(payload&&payload.createdAt||0);
  if(createdAt&&Date.now()-createdAt>2*60*60*1000){
    try{sessionStorage.removeItem(CREATE_PHONE_PENDING_KEY);}catch(_e){}
    return'';
  }
  const phone=normalizePendingCreatePhone(payload&&payload.phone||'');
  if(phone){
    try{sessionStorage.removeItem(CREATE_PHONE_PENDING_KEY);}catch(_e){}
    return phone;
  }
  return'';
}
function getLocalPhoneDigits(value){let d=String(value||'').replace(/\D/g,'');if(d.startsWith('7'))d=d.slice(1);else if(d.startsWith('8')&&d.length>=11)d=d.slice(1);if(d.length>10)d=d.slice(0,10);return d;}
function formatLocalPhone(value){const d=getLocalPhoneDigits(value);if(!d)return'+7';if(d.length<=3)return`+7 ${d}`;let out=`+7 ${d.slice(0,3)}-${d.slice(3,6)}`;if(d.length>6)out+=`-${d.slice(6,10)}`;return out;}
