function applyTmReadonlyStripe(el){
  if(!el)return;
  try{
    ensureTmReadonlyStripeStyle();
    if(!el.readOnly)el.readOnly=true;
    if(!el.hasAttribute('readonly'))el.setAttribute('readonly','readonly');
    if(el.getAttribute('data-tm-stripe-readonly')!=='1')el.setAttribute('data-tm-stripe-readonly','1');
    if(!el.classList.contains('tm-readonly-stripe'))el.classList.add('tm-readonly-stripe');
    if(el.hasAttribute('disabled'))el.removeAttribute('disabled');
    if(el.hasAttribute('aria-disabled'))el.removeAttribute('aria-disabled');
    if(el.style.cursor!=='text')el.style.cursor='text';
    if(el.style.userSelect!=='text')el.style.userSelect='text';
    if(el.style.webkitUserSelect!=='text')el.style.webkitUserSelect='text';
  }catch(_){}
}
