function tmBuildDobitServiceComment(text,targetLine){
  targetLine=String(targetLine||'Добить').trim()||'Добить';
  var targetLower=targetLine.toLowerCase();
  var src=String(text||'');
  var alreadyHasTarget=src.split('\n').some(function(line){
    return String(line||'').trim().toLowerCase()===targetLower;
  });
  if(alreadyHasTarget)return src;
  function hasAddressPhrase(v){
    var t=String(v||'').toLowerCase();
    return t.indexOf('адрес не говорил')!==-1||
      t.indexOf('адрес не называл')!==-1||
      t.indexOf('адрес не знаем')!==-1||
      t.indexOf('адрес неизвестен')!==-1||
      t.indexOf('адрес не указан')!==-1||
      t.indexOf('не сказал адрес')!==-1;
  }
  function hasDobit(v){return String(v||'').toLowerCase().indexOf('добить')!==-1;}
  var out=[];
  src.split('\n').forEach(function(line){
    var ln=String(line||'').trim();
    if(!ln)return;
    var low=ln.toLowerCase();
    var hasDate=/\d{2}\.\d{2}\.\d{2}\s+\d{2}:\d{2}/.test(ln);
    if(hasDate&&low.indexOf('не отвечает')!==-1)return;
    if(hasDobit(ln))return;
    if(hasAddressPhrase(ln))return;
    out.push(ln);
  });
  out.push(targetLine);
  return out.join('\n');
}
function tmApplyDobitToServiceComment(ev){
  var withAddress=!!(ev&&(ev.ctrlKey||ev.metaKey));
  var targetLine=withAddress?'Добить, адрес не говорил':'Добить';
  var cse=getUiServiceCommentField();
  var bridgeVal='';
  try{bridgeVal=pickBestBridgeServiceCommentValue()||'';}catch(_){}
  var src=((cse&&cse.value)||bridgeVal||'');
  var newVal=tmBuildDobitServiceComment(src,targetLine);
  if(cse){
    cse.value=newVal;
    try{cc(cse,'n2');}catch(_){}
    cse.dispatchEvent(new Event('input',{bubbles:true}));
    try{cse.dispatchEvent(new KeyboardEvent('keyup',{bubbles:true,cancelable:true,key:'t'}));}catch(_){}
    cse.dispatchEvent(new Event('change',{bubbles:true}));
    cse.dispatchEvent(new Event('blur',{bubbles:true}));
  }
  try{
    getBridgeServiceCommentTargets().forEach(function(t){
      if(!t)return;
      t.value=newVal;
      t.dispatchEvent(new Event('input',{bubbles:true}));
      t.dispatchEvent(new Event('change',{bubbles:true}));
      t.dispatchEvent(new Event('blur',{bubbles:true}));
    });
  }catch(_){}
  syncSourceServiceComment(newVal,0,{forceBlur:true});
  setTimeout(function(){syncSourceServiceComment(newVal,0,{forceBlur:true});},20);
}
function ensureCreateDobitButton(){
  if(!/\/customer-request\/create/i.test(String(location.pathname||'')))return;
  var block=document.querySelector('.service-comment');
  var lbl=block&&block.querySelector('.fl');
  if(!lbl||lbl.querySelector('#tmCreateDobitBtn'))return;
  var btn=document.createElement('button');
  btn.id='tmCreateDobitBtn';
  btn.type='button';
  btn.style.cssText='border:none;background:none;cursor:pointer;padding:0;font-size:9.5px;font-weight:600;color:var(--ac);font-family:var(--font);text-transform:uppercase;letter-spacing:.05em;white-space:nowrap;display:inline-flex;align-items:center;gap:3px;line-height:1;';
  btn.innerHTML='<i class="ti ti-check" style="font-size:10px"></i>Добить';
  btn.title='Добавить в служебный комментарий. Ctrl+клик: "Добить, адрес не говорил"';
  btn.addEventListener('click',function(e){
    e.preventDefault();
    e.stopPropagation();
    tmApplyDobitToServiceComment(e);
  });
  try{
    lbl.style.display='flex';
    lbl.style.alignItems='center';
    if(!lbl.style.gap)lbl.style.gap='8px';
  }catch(_){}
  var spacer=document.createElement('span');
  spacer.style.cssText='margin-left:auto;display:inline-flex;align-items:center;';
  spacer.appendChild(btn);
  lbl.appendChild(spacer);
}
