function findRequestDocumentsSource(){
  var roots=[];
  try{roots.push(document);}catch(_){}
  try{var bd=getBridgeDoc();if(bd&&roots.indexOf(bd)===-1)roots.push(bd);}catch(_){}
  for(var r=0;r<roots.length;r++){
    var root=roots[r];
    if(!root||!root.querySelector)return null;
    var link=root.querySelector('a.nav-link[href="#photo"],a[href="#photo"],a[role="tab"][href="#photo"]');
    var pane=null;
    if(link){
      var href=String(link.getAttribute('href')||'').trim();
      if(href.charAt(0)==='#'){
        try{pane=root.getElementById(href.slice(1));}catch(_){}
      }
    }
    pane=pane||root.querySelector('#photo,.tab-pane#photo');
    if(pane&&!(pane.closest&&pane.closest('#tmRequestDocumentsDialog')))return pane;
    var form=root.querySelector('form#w2,form[action*="photo"],form[action*="document"]');
    if(form&&!(form.closest&&form.closest('#tmRequestDocumentsDialog')))return form;
    var body=root.querySelector('form#w2 > .card > .card-body');
    if(body&&!(body.closest&&body.closest('#tmRequestDocumentsDialog')))return body;
  }
  return null;
}
function classifyRequestDocumentByText(txt){
  var t=String(txt||'').toLowerCase().replace(/ё/g,'е');
  if(t.indexOf('сохран')!==-1||t.indexOf('расписк')!==-1)return 'receipt';
  if(t.indexOf('фото')!==-1||t.indexOf('запчаст')!==-1)return 'parts_photo';
  if(t.indexOf('расход')!==-1||t.indexOf('комплектующ')!==-1)return 'parts_checks';
  if(t.indexOf('договор')!==-1||t.indexOf('чек')!==-1||t.indexOf('услуг')!==-1)return 'service_checks';
  return '';
}
function collectRequestDocumentImages(){
  var source=findRequestDocumentsSource();
  var groups={
    service_checks:[],
    parts_checks:[],
    parts_photo:[],
    receipt:[]
  };
  if(!source)return groups;
  function absUrl(v){
    try{return new URL(String(v||''),location.href).toString();}catch(_){return String(v||'');}
  }
  function getImgUrl(img){
    var attrs=['data-original','data-src','data-url','src','href'];
    for(var i=0;i<attrs.length;i++){
      var v=img.getAttribute&&img.getAttribute(attrs[i]);
      if(v&&String(v).trim()&&!/^data:image\/svg/i.test(String(v)))return absUrl(v);
    }
    var a=img.closest&&img.closest('a[href]');
    if(a&&/\.(png|jpe?g|webp|gif|bmp)(?:[?#]|$)/i.test(a.getAttribute('href')||''))return absUrl(a.getAttribute('href'));
    return '';
  }
  function nearbyText(el){
    var parts=[];
    var n=el;
    for(var depth=0;n&&depth<6;depth++,n=n.parentElement){
      var txt=__tmNormTxt(n.textContent||'');
      if(txt)parts.push(txt);
      var prev=n.previousElementSibling;
      for(var k=0;prev&&k<3;k++,prev=prev.previousElementSibling){
        var pt=__tmNormTxt(prev.textContent||'');
        if(pt)parts.push(pt);
      }
    }
    return parts.join(' ');
  }
  function directGroupText(el){
    var frame=el.closest&&el.closest('.file-preview-frame,.krajee-default,.file-thumb-frame,.file-preview-initial,.file-input,.form-group,[class*="field-"]');
    var parts=[];
    var n=frame||el;
    function add(v){v=__tmNormTxt(v||'');if(v)parts.push(v);}
    for(var depth=0;n&&depth<7;depth++,n=n.parentElement){
      add(n.querySelector&&n.querySelector('label,.control-label,.help-block')&&n.querySelector('label,.control-label,.help-block').textContent);
      var prev=n.previousElementSibling;
      for(var k=0;prev&&k<5;k++,prev=prev.previousElementSibling){
        add(prev.textContent);
        var key=classifyRequestDocumentByText(parts.join(' '));
        if(key)return parts.join(' ');
      }
      var parent=n.parentElement;
      if(parent){
        var kids=Array.from(parent.children||[]);
        var idx=kids.indexOf(n);
        for(var j=Math.max(0,idx-3);j<idx;j++){
          add(kids[j]&&kids[j].textContent);
          var key2=classifyRequestDocumentByText(parts.join(' '));
          if(key2)return parts.join(' ');
        }
      }
      var key3=classifyRequestDocumentByText(parts.join(' '));
      if(key3)return parts.join(' ');
    }
    return parts.join(' ');
  }
  function sectionKeyByImagePosition(img){
    var key=classifyRequestDocumentByText(directGroupText(img));
    if(key)return key;
    key=classifyRequestDocumentByText(nearbyText(img));
    if(key)return key;
    var fields=Array.from(source.querySelectorAll('.form-group,.field-claimform-files,.file-input,[class*="field-"]')).filter(function(el){
      return el.querySelector&&el.querySelector('img');
    });
    var holder=img.closest&&img.closest('.form-group,.file-input,[class*="field-"]');
    var pos=fields.indexOf(holder);
    if(pos===0)return 'service_checks';
    if(pos===1)return 'parts_checks';
    if(pos===2)return 'parts_photo';
    if(pos>=3)return 'receipt';
    return 'service_checks';
  }
  var imgs=Array.from(source.querySelectorAll('img')).filter(function(img){
    var url=getImgUrl(img);
    if(!url)return false;
    var w=Number(img.naturalWidth||img.width||0),h=Number(img.naturalHeight||img.height||0);
    var cls=String(img.className||'').toLowerCase();
    if((w&&w<24)||(h&&h<24))return false;
    if(cls.indexOf('krajee-default-preview')===-1&&/icon|loader|spinner|folder/i.test(cls))return false;
    return true;
  });
  var seen=new Set();
  imgs.forEach(function(img){
    var url=getImgUrl(img);
    if(!url||seen.has(url))return;
    seen.add(url);
    var key=sectionKeyByImagePosition(img)||'service_checks';
    var name=(img.getAttribute('title')||img.getAttribute('alt')||'').trim();
    if(!name){
      var cap=img.closest&&img.closest('.file-preview-frame,.krajee-default,.file-thumb-frame,.file-preview-initial');
      name=__tmNormTxt((cap&&cap.textContent)||'');
      name=name.replace(/^(инициализация|загрузка)\s*/i,'').trim();
    }
    groups[key].push({url:url,name:name||'Фото'});
  });
  return groups;
}
function openRequestDocumentViewer(item){
  ensureRequestDocumentsStyle();
  var old=document.getElementById('tmRequestDocViewer');
  if(old)old.remove();
  var viewer=document.createElement('div');
  viewer.id='tmRequestDocViewer';
  viewer.className='tm-docs-viewer';
  var stage=document.createElement('div');
  stage.className='tm-docs-viewer-stage';
  var img=document.createElement('img');
  img.className='tm-docs-viewer-img';
  img.src=item.url;
  img.draggable=false;
  img.setAttribute('draggable','false');
  stage.appendChild(img);
  var close=document.createElement('button');
  close.type='button';
  close.className='tm-docs-viewer-close';
  close.innerHTML='<i class="ti ti-x"></i>';
  viewer.appendChild(stage);
  viewer.appendChild(close);
  document.body.appendChild(viewer);
  var scale=1,tx=0,ty=0,drag=false,sx=0,sy=0,stx=0,sty=0;
  function getBaseSize(){
    var sr=stage.getBoundingClientRect();
    var iw=Number(img.naturalWidth||img.width||1);
    var ih=Number(img.naturalHeight||img.height||1);
    var fit=Math.min(sr.width/iw,sr.height/ih,1);
    return{stageW:sr.width,stageH:sr.height,w:iw*fit,h:ih*fit};
  }
  function clampPan(){
    var b=getBaseSize();
    var freeX=Math.max(b.stageW*2.2,b.w*scale);
    var freeY=Math.max(b.stageH*2.2,b.h*scale);
    tx=Math.max(-freeX,Math.min(freeX,tx));
    ty=Math.max(-freeY,Math.min(freeY,ty));
  }
  function apply(){
    clampPan();
    img.style.width=getBaseSize().w+'px';
    img.style.height='auto';
    img.style.transform='translate3d('+tx+'px,'+ty+'px,0) scale('+scale+')';
  }
  function setScale(next,cx,cy){
    var prev=scale;
    next=Math.max(.25,Math.min(6,next));
    var hasPoint=typeof cx==='number'&&typeof cy==='number';
    if(next>prev&&hasPoint){
      var sr=stage.getBoundingClientRect();
      var dx=cx-(sr.left+sr.width/2);
      var dy=cy-(sr.top+sr.height/2);
      var ratio=next/Math.max(prev,.01);
      tx=dx-(dx-tx)*ratio;
      ty=dy-(dy-ty)*ratio;
    }
    if(next<prev){
      var pull=Math.min(.92,(prev-next)/Math.max(prev,.01)*1.75);
      tx=tx*(1-pull);
      ty=ty*(1-pull);
      if(next<=1.001){
        tx=0;
        ty=0;
      }
    }
    scale=next;
    apply();
  }
  close.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();viewer.classList.remove('open');setTimeout(function(){viewer.remove();},280);});
  viewer.addEventListener('click',function(e){if(e.target===viewer)close.click();});
  viewer.addEventListener('wheel',function(e){e.preventDefault();setScale(scale*(e.deltaY<0?1.12:.89),e.clientX,e.clientY);},{passive:false});
  function preventNativeImageDrag(e){try{e.preventDefault();e.stopPropagation();}catch(_){} return false;}
  img.addEventListener('dragstart',preventNativeImageDrag,true);
  img.addEventListener('selectstart',preventNativeImageDrag,true);
  img.addEventListener('mousedown',preventNativeImageDrag,true);
  stage.addEventListener('pointerdown',function(e){
    if(e.button!=null&&e.button!==0)return;
    e.preventDefault();
    drag=true;
    sx=e.clientX;
    sy=e.clientY;
    stx=tx;
    sty=ty;
    stage.classList.add('dragging');
    try{stage.setPointerCapture(e.pointerId);}catch(_){}
  });
  stage.addEventListener('pointermove',function(e){
    if(!drag)return;
    e.preventDefault();
    tx=stx+(e.clientX-sx);
    ty=sty+(e.clientY-sy);
    apply();
  });
  function endStageDrag(e){
    if(!drag)return;
    drag=false;
    stage.classList.remove('dragging');
    try{if(e&&e.pointerId!=null)stage.releasePointerCapture(e.pointerId);}catch(_){}
  }
  stage.addEventListener('pointerup',endStageDrag);
  stage.addEventListener('pointercancel',endStageDrag);
  stage.addEventListener('lostpointercapture',endStageDrag);
  img.addEventListener('load',function(){apply();});
  window.addEventListener('resize',apply,{passive:true});
  requestAnimationFrame(function(){viewer.classList.add('open');});
}
function closeRequestDocumentsDialog(){
  var dlg=document.getElementById('tmRequestDocumentsDialog');
  if(dlg)dlg.classList.remove('open');
  setTimeout(function(){
    window.__tmRequestDocumentsMount=null;
    try{if(dlg)dlg.remove();}catch(_){}
  },300);
}
function openRequestDocumentsDialog(){
  ensureRequestDocumentsStyle();
  var groups=collectRequestDocumentImages();
  var total=Object.keys(groups).reduce(function(sum,k){return sum+(groups[k]||[]).length;},0);
  if(!total){
    try{showToast('Документы не найдены');}catch(_){}
  }
  var old=document.getElementById('tmRequestDocumentsDialog');
  if(old)closeRequestDocumentsDialog();
  var backdrop=document.createElement('div');
  backdrop.id='tmRequestDocumentsDialog';
  backdrop.className='tm-docs-backdrop';
  var dialog=document.createElement('div');
  dialog.className='tm-docs-dialog';
  var head=document.createElement('div');
  head.className='tm-docs-head';
  head.innerHTML='<div class="tm-docs-ico"><i class="ti ti-files"></i></div><div><div class="tm-docs-title">Документы</div><div class="tm-docs-sub">Фотографии и файлы заявки</div></div><div class="tm-docs-spacer"></div>';
  var close=document.createElement('button');
  close.type='button';
  close.className='tm-docs-close';
  close.innerHTML='<i class="ti ti-x"></i>';
  close.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();closeRequestDocumentsDialog();});
  head.appendChild(close);
  var body=document.createElement('div');
  body.className='tm-docs-body';
  var content=document.createElement('div');
  content.className='tm-docs-content';
  body.appendChild(content);
  dialog.appendChild(head);
  dialog.appendChild(body);
  backdrop.appendChild(dialog);
  backdrop.addEventListener('click',function(e){if(e.target===backdrop)closeRequestDocumentsDialog();});
  document.body.appendChild(backdrop);
  [
    {key:'service_checks',title:'Договор/Чеки на услуги',ico:'ti-file-invoice'},
    {key:'parts_checks',title:'Чеки на комплектующие/расходы',ico:'ti-receipt'},
    {key:'parts_photo',title:'Фото запчастей/комплектующих',ico:'ti-photo'},
    {key:'receipt',title:'Сохранная расписка',ico:'ti-file-check'}
  ].forEach(function(sec){
    var section=document.createElement('section');
    section.className='tm-docs-section';
    var sh=document.createElement('div');
    sh.className='tm-docs-section-head';
    sh.innerHTML='<i class="ti '+sec.ico+'"></i><div class="tm-docs-section-title">'+sec.title+'</div>';
    var grid=document.createElement('div');
    grid.className='tm-docs-grid';
    var arr=groups[sec.key]||[];
    if(arr.length){
      arr.forEach(function(item){
        var thumb=document.createElement('button');
        thumb.type='button';
        thumb.className='tm-docs-thumb';
        var im=document.createElement('img');
        im.src=item.url;
        im.alt=item.name||sec.title;
        var cap=document.createElement('div');
        cap.className='tm-docs-thumb-name';
        cap.textContent=item.name||sec.title;
        thumb.appendChild(im);
        thumb.appendChild(cap);
        thumb.addEventListener('click',function(e){
          e.preventDefault();
          e.stopPropagation();
          openRequestDocumentViewer(item);
        });
        grid.appendChild(thumb);
      });
    }else{
      var empty=document.createElement('div');
      empty.className='tm-docs-empty';
      empty.textContent='Фотографий нет';
      grid.appendChild(empty);
    }
    section.appendChild(sh);
    section.appendChild(grid);
    content.appendChild(section);
  });
  requestAnimationFrame(function(){backdrop.classList.add('open');});
}
function ensureRequestDocumentsButton(opts){
  opts=opts||{};
  if(!/\/customer-request\/update/i.test(String(location.pathname||'')))return;
  if(opts.isModeration||opts.isClarification||isModerationOrClarificationStatusNow())return;
  var cardHd=document.querySelector('#tmClientCard .card-hd');
  var host=null;
  if(cardHd){
    host=cardHd.querySelector('#tmClientHeaderActions');
    if(!host){
      host=document.createElement('div');
      host.id='tmClientHeaderActions';
      host.className='tm-client-hd-actions';
      host.style.cssText='margin-left:auto;display:flex;align-items:center;justify-content:flex-end;gap:8px;flex:0 0 auto;';
      cardHd.appendChild(host);
    }
  }
  var topbar=document.querySelector('.topbar');
  host=host||topbar;
  if(!host)return;
  var old=document.getElementById('tmRequestDocumentsBtn');
  if(old){
    if(old.parentNode===host)return;
    try{old.remove();}catch(_){}
  }
  var btn=document.createElement('button');
  btn.id='tmRequestDocumentsBtn';
  btn.type='button';
  btn.className='tm-docs-header-btn';
  btn.title='Документы';
  btn.setAttribute('aria-label','Документы');
  btn.style.cssText='position:relative;display:inline-flex;align-items:center;justify-content:center;width:28px;height:22px;border:.5px solid var(--br2);border-radius:7px;background:var(--bg0);color:var(--t1);cursor:pointer;transition:all .12s;padding:0;flex:0 0 28px;';
  btn.innerHTML='<span style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;"><i class="ti ti-files" style="display:block;font-size:14px;line-height:1;transform:translateY(0)"></i></span>';
  btn.addEventListener('mouseenter',function(){btn.style.background='var(--bg1)';btn.style.borderColor='var(--br2)';btn.style.color='var(--t0)';});
  btn.addEventListener('mouseleave',function(){btn.style.background='var(--bg0)';btn.style.borderColor='var(--br2)';btn.style.color='var(--t1)';});
  btn.addEventListener('click',function(e){
    e.preventDefault();
    e.stopPropagation();
    openRequestDocumentsDialog();
  });
  if(host.id==='tmClientHeaderActions')host.insertBefore(btn,host.firstChild||null);
  else host.appendChild(btn);
}
function activateNativeCommentFocusFromUi(){
  try{
    var lockUntil=Number(activateNativeCommentFocusFromUi.__lockUntil||0);
    var nowTs=Date.now();
    if(nowTs<lockUntil)return false;
    activateNativeCommentFocusFromUi.__lockUntil=nowTs+50;
    var commInp=getUiMainCommentField();
    if(!commInp)return false;
    var commVal=commInp.value||'';
    var natComment=document.getElementById('customerrequest-comments')
      ||document.querySelector('textarea[name="CustomerRequest[comments]"]')
      ||document.getElementById('customerrequest-comment')
      ||document.querySelector('textarea[name="CustomerRequest[comment]"]');
    if(natComment){
      var changedNat=String(natComment.value||'')!==String(commVal);
      if(changedNat)natComment.value=commVal;
      try{
        if(ensureBridgeActiveElementShim(document)){
          document.__tmForcedActiveElement=natComment;
        }
      }catch(_){}
      try{natComment.dispatchEvent(new FocusEvent('focus',{bubbles:false}));}catch(_e1){try{natComment.dispatchEvent(new Event('focus'));}catch(_e1b){}}
      try{natComment.dispatchEvent(new FocusEvent('focusin',{bubbles:true}));}catch(_e2){try{natComment.dispatchEvent(new Event('focusin',{bubbles:true}));}catch(_e2b){}}
      if(changedNat){
        try{natComment.dispatchEvent(new Event('input',{bubbles:true}));}catch(_e3){}
      }
      setTimeout(function(){try{document.__tmForcedActiveElement=null;}catch(_){}} ,25);
    }
    try{syncSourceComment(commVal,0,{forceFocusSignal:true});}catch(_){}
    return true;
  }catch(_){return false;}
}
function fireCommentAutotypeKickAfterFirstCity(){
  try{
    var commInp=getUiMainCommentField();
    var natComment=tmGetNativeMainCommentField();
    var commVal=String((commInp&&commInp.value)||'');
    if(!commVal.trim())return false;
    if(natComment&&commInp&&natComment!==commInp&&String(natComment.value||'')!==commVal){
      natComment.value=commVal;
    }
    function fire(el,focusReal){
      if(!el)return;
      var w=(el.ownerDocument&&el.ownerDocument.defaultView)||window;
      if(focusReal){
        try{if(typeof el.focus==='function')el.focus({preventScroll:true});}catch(_f1){try{el.focus();}catch(_f2){}}
      }
      try{el.dispatchEvent(new FocusEvent('focus',{bubbles:false}));}catch(_e1){try{el.dispatchEvent(new Event('focus'));}catch(_e1b){}}
      try{el.dispatchEvent(new FocusEvent('focusin',{bubbles:true}));}catch(_e2){try{el.dispatchEvent(new Event('focusin',{bubbles:true}));}catch(_e2b){}}
      try{el.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true,view:w,button:0,buttons:1}));}catch(_e3){}
      try{el.dispatchEvent(new MouseEvent('mouseup',{bubbles:true,cancelable:true,view:w,button:0,buttons:0}));}catch(_e4){}
      try{el.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true,view:w,button:0,buttons:1}));}catch(_e5){}
      try{el.dispatchEvent(new Event('input',{bubbles:true}));}catch(_e6){}
      try{el.dispatchEvent(new Event('change',{bubbles:true}));}catch(_e7){}
      if(focusReal){
        try{if(typeof el.blur==='function')el.blur();}catch(_b1){}
      }else{
        try{el.dispatchEvent(new FocusEvent('blur',{bubbles:false,relatedTarget:null}));}catch(_b2){try{el.dispatchEvent(new Event('blur'));}catch(_b2b){}}
        try{el.dispatchEvent(new FocusEvent('focusout',{bubbles:true,relatedTarget:null}));}catch(_b3){try{el.dispatchEvent(new Event('focusout',{bubbles:true}));}catch(_b3b){}}
      }
    }
    // Короткий полный цикл focus -> blur запускает Фикс+ахк, но не оставляет
    // курсор в комментарии после выбора города.
    fire(commInp,true);
    if(natComment&&natComment!==commInp)fire(natComment,false);
    try{syncSourceComment(commVal,0,{forceNotify:true,forceFocusSignal:true,forceBlur:true});}catch(_){}
    try{
      var bridgeDoc=getBridgeDoc();
      var typeSel=bridgeDoc&&(bridgeDoc.getElementById('customerrequest-appliance_type_id')||bridgeDoc.querySelector('select[name="CustomerRequest[appliance_type_id]"]'));
      var typeInp=document.getElementById('appTypeInput');
      var typeText=typeSel&&typeSel.selectedIndex>0&&typeSel.options[typeSel.selectedIndex]
        ?String(typeSel.options[typeSel.selectedIndex].text||'').trim()
        :'';
      if(typeInp&&typeText){
        typeInp.value=typeText;
        syncSubByText(typeText);
        syncCreatePrereqLocks();
      }
    }catch(_){}
    try{syncWorkSelectionFromComment();}catch(_){}
    return true;
  }catch(_){return false;}
}
