var _commLastUiValueForExternalMerge='';
function tmGetNativeMainCommentField(){
  return document.getElementById('customerrequest-comments')
    ||document.querySelector('textarea[name="CustomerRequest[comments]"]')
    ||document.getElementById('customerrequest-comment')
    ||document.querySelector('textarea[name="CustomerRequest[comment]"]')
    ||null;
}
function tmRememberUiMainCommentValue(field){
  try{
    var v=String((field&&field.value)||'').replace(/\r/g,'');
    _commLastUiValueForExternalMerge=v;
    if(field&&field.dataset)field.dataset.tmLastUiMainCommentValue=v;
  }catch(_){}
}
function tmMergeExternalNativeMainCommentIntoUi(field){
  try{
    var ta=field||getUiMainCommentField();
    if(!ta)return false;
    var native=tmGetNativeMainCommentField();
    if(!native||native===ta)return false;
    var cur=String(ta.value||'').replace(/\r/g,'');
    var nat=String(native.value||'').replace(/\r/g,'');
    if(!nat||nat===cur)return false;
    var prev=String((ta.dataset&&ta.dataset.tmLastUiMainCommentValue)||_commLastUiValueForExternalMerge||'').replace(/\r/g,'');

    // Если native всё ещё равен прошлому UI, а пользователь уже меняет текст,
    // это удаление/редактирование, а не новая внешняя вставка. Не возвращаем хвост.
    if(prev&&nat===prev&&cur!==prev)return false;

    var base='';
    if(prev&&nat.indexOf(prev)===0&&nat.length>prev.length)base=prev;
    else if(cur&&nat.indexOf(cur)===0&&nat.length>cur.length)base=cur;
    else if(!cur&&nat)base='';
    else return false;

    var next;
    if(base==='')next=nat;
    else next=cur+nat.slice(base.length);
    if(next===cur)return false;

    var active=document.activeElement===ta;
    var ss=active&&typeof ta.selectionStart==='number'?ta.selectionStart:null;
    var se=active&&typeof ta.selectionEnd==='number'?ta.selectionEnd:null;
    ta.value=next;
    if(active&&ss!==null){
      try{ta.setSelectionRange(Math.min(ss,next.length),Math.min(se,next.length));}catch(_e1){}
    }
    try{tmAutosizeTextarea(ta);}catch(_e2){}
    try{cc(ta,'n1');}catch(_e3){}
    tmRememberUiMainCommentValue(ta);
    return true;
  }catch(_){return false;}
}
