function tmExtractActiveWorkStatusFromText(value){
  var txt=String(value||'').toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
  if(!txt)return'';
  var after=txt.match(/статус\s*:\s*([а-яе\s]+?)(?:\s{2,}|$)/i);
  var probe=after?String(after[1]||'').toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim():txt;
  if(/(^|\s)в работе сд(\s|$)/.test(probe))return'В работе СД';
  if(/(^|\s)в работе(\s|$)/.test(probe))return'В работе';
  if(/(^|\s)в пути(\s|$)/.test(probe))return'В пути';
  if(/(^|\s)ожидает(\s|$)/.test(probe))return'Ожидает';
  return'';
}
