function tmSendCityChatPostSaveAhk(city,message,onceKey){
  city=String(city||'').trim();
  message=String(message||'').trim();
  onceKey=String(onceKey||'').trim();
  if(!city||!message){
    tmWriteCityChatPostSaveDebug('send_skip',{
      reason:!city?'no_city':'no_message',
      city:city,
      message:message,
      onceKey:onceKey
    });
    return false;
  }
  var sentKey=onceKey?(TM_CITY_CHAT_POST_SAVE_SENT_PREFIX+onceKey):'';
  if(sentKey){
    try{
      var prev=Number(sessionStorage.getItem(sentKey)||0);
      if(prev&&Date.now()-prev<120000){
        tmWriteCityChatPostSaveDebug('send_dedupe',{
          city:city,
          message:message,
          onceKey:onceKey
        });
        return true;
      }
      sessionStorage.setItem(sentKey,String(Date.now()));
    }catch(_){}
  }
  if(typeof GM_xmlhttpRequest!=='function'){
    if(sentKey){
      try{sessionStorage.removeItem(sentKey);}catch(_clearNoGm){}
    }
    tmWriteCityChatPostSaveDebug('send_no_gm',{
      city:city,
      message:message,
      onceKey:onceKey
    });
    return false;
  }
  try{
    tmWriteCityChatPostSaveDebug('send_dispatch',{
      city:city,
      message:message,
      onceKey:onceKey
    });
    GM_xmlhttpRequest({
      method:'GET',
      url:'http://127.0.0.1:12348/?city='+encodeURIComponent(city)+'&message='+encodeURIComponent(message)+'&_t='+Date.now(),
      timeout:3000,
      onload:function(response){
        var status=response&&response.status||0;
        tmWriteCityChatPostSaveDebug('send_onload',{
          city:city,
          message:message,
          onceKey:onceKey,
          status:status,
          ok:status===200
        });
        if(status!==200&&sentKey){
          try{sessionStorage.removeItem(sentKey);}catch(_clearBadStatus){}
        }
      },
      onerror:function(){
        if(sentKey){
          try{sessionStorage.removeItem(sentKey);}catch(_clearOnError){}
        }
        tmWriteCityChatPostSaveDebug('send_onerror',{
          city:city,
          message:message,
          onceKey:onceKey
        });
      },
      ontimeout:function(){
        if(sentKey){
          try{sessionStorage.removeItem(sentKey);}catch(_clearOnTimeout){}
        }
        tmWriteCityChatPostSaveDebug('send_ontimeout',{
          city:city,
          message:message,
          onceKey:onceKey
        });
      }
    });
    return true;
  }catch(err){
    if(sentKey){
      try{sessionStorage.removeItem(sentKey);}catch(_clearSendEx){}
    }
    tmWriteCityChatPostSaveDebug('send_exception',{
      city:city,
      message:message,
      onceKey:onceKey,
      error:String((err&&err.message)||err||'')
    });
    return false;
  }
}
