function tmReadLiveAddressSnapshot(){
  function clean(v){return normalizeCustomerUpdateCompareText(v);}
  var snap={locality:'',street:'',house:'',city:''};
  try{
    var roots=[];
    function add(root){
      try{if(root&&root.querySelector&&roots.indexOf(root)===-1)roots.push(root);}catch(_){}
    }
    add(document);
    try{add(window.__tmNativeRequestForm);}catch(_){}
    try{add(window.__tmCrmFormHolder);}catch(_){}
    try{add(document.getElementById('tmCrmFormHolder'));}catch(_){}
    try{if(typeof getBridgeDoc==='function')add(getBridgeDoc());}catch(_){}
    for(var i=0;i<roots.length;i++){
      var root=roots[i];
      if(!snap.locality){
        var locality=root.querySelector('#customer-address_locality, input[name="Customer[address_locality]"]');
        snap.locality=clean(locality&&locality.value);
      }
      if(!snap.street){
        var street=root.querySelector('#customer-address_street, input[name="Customer[address_street]"]');
        snap.street=clean(street&&street.value);
      }
      if(!snap.house){
        var house=root.querySelector('#customer-address_building, input[name="Customer[address_building]"]');
        snap.house=clean(house&&house.value);
      }
      if(!snap.city){
        var citySel=root.querySelector('#customerrequest-city_id, select[name="CustomerRequest[city_id]"], #customer-city_id, select[name="Customer[city_id]"]');
        if(citySel){
          var cityOpt=citySel.options&&citySel.options[citySel.selectedIndex];
          snap.city=clean((cityOpt&&cityOpt.text)||citySel.value||'');
          if(/^выберите/i.test(snap.city))snap.city='';
        }
      }
      if(snap.locality||snap.street||snap.house){
        if(snap.locality&&snap.street&&snap.house&&snap.city)break;
      }
    }
  }catch(_){}
  if(!snap.locality){
    try{snap.locality=clean((document.getElementById('addrLocality')||{}).value||'');}catch(_uiLocality){}
  }
  if(!snap.street){
    try{snap.street=clean((document.getElementById('addrStreet')||{}).value||'');}catch(_uiStreet){}
  }
  if(!snap.house){
    try{snap.house=clean((document.getElementById('addrHouse')||{}).value||'');}catch(_uiHouse){}
  }
  if(!snap.city){
    try{snap.city=clean(tmGetUiCityChatTarget());}catch(_){}
  }
  return snap;
}
