function tmParseHmToMinutes(value){
  var m=String(value||'').trim().match(/^(\d{1,2}):(\d{2})$/);
  if(!m)return null;
  var hh=Number(m[1]),mm=Number(m[2]);
  if(!(hh>=0&&hh<=23&&mm>=0&&mm<=59))return null;
  return hh*60+mm;
}
function tmParseRequestDateTimeMs(snap){
  try{
    snap=snap||{};
    var iso=parseBridgeIsoDate(String(snap.date||'').trim());
    var hm=String(snap.time||'').trim();
    var dm=iso.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    var tm=hm.match(/^(\d{2}):(\d{2})$/);
    if(!dm||!tm)return null;
    return new Date(Number(dm[1]),Number(dm[2])-1,Number(dm[3]),Number(tm[1]),Number(tm[2]),0,0).getTime();
  }catch(_){
    return null;
  }
}
function tmGetRequestDateTimeChangeMinutes(beforeSnap,nextSnap){
  try{
    var beforeMs=tmParseRequestDateTimeMs(beforeSnap);
    var nextMs=tmParseRequestDateTimeMs(nextSnap);
    if(beforeMs!==null&&nextMs!==null){
      return Math.abs(Math.round((nextMs-beforeMs)/60000));
    }
    var beforeTime=tmParseHmToMinutes((beforeSnap||{}).time||'');
    var nextTime=tmParseHmToMinutes((nextSnap||{}).time||'');
    if(beforeTime===null||nextTime===null)return null;
    var beforeDate=String((beforeSnap||{}).date||'').trim();
    var nextDate=String((nextSnap||{}).date||'').trim();
    if(beforeDate&&nextDate&&beforeDate!==nextDate)return null;
    var diff=Math.abs(nextTime-beforeTime);
    return Math.min(diff,1440-diff);
  }catch(_){
    return null;
  }
}
