    if(n.indexOf('тв ')===0||n==='тв')s=s.replace(/^\s*тв(?=\s|$)/i,'Телевизор');
    if(n.indexOf('пс5 ')===0||n==='пс5'||n.indexOf('ps5 ')===0||n==='ps5')s=s.replace(/^\s*(пс5|ps5)(?=\s|$)/i,'PlayStation 5');
    if(n.indexOf('пс4 ')===0||n==='пс4'||n.indexOf('ps4 ')===0||n==='ps4')s=s.replace(/^\s*(пс4|ps4)(?=\s|$)/i,'PlayStation 4');
    if(n.indexOf('пс3 ')===0||n==='пс3'||n.indexOf('ps3 ')===0||n==='ps3')s=s.replace(/^\s*(пс3|ps3)(?=\s|$)/i,'PlayStation 3');
    if(n.indexOf('пс ')===0||n==='пс'||n.indexOf('ps ')===0||n==='ps')s=s.replace(/^\s*(пс|ps)(?=\s|$)/i,'PlayStation');
    if(n.indexOf('xbox ')===0||n==='xbox'||n.indexOf('иксбокс ')===0||n==='иксбокс')s=s.replace(/^\s*(xbox|иксбокс)(?=\s|$)/i,'Xbox');
    if(n.indexOf('nintendo ')===0||n==='nintendo'||n.indexOf('нинтендо ')===0||n==='нинтендо')s=s.replace(/^\s*(nintendo\s*switch|nintendo|нинтендо\s*свич|нинтендо)(?=\s|$)/i,'Nintendo switch');
