    var mainPh=document.querySelector('#customer-phone')||ensureSourcePhone(0);
    var bridgePh=getBridgeSourcePhoneEl();
    var mainVal=String(mainPh&&mainPh.value||'');
    var bridgeVal=String(bridgePh&&bridgePh.value||'');
