    if(!uiPh)return;
    var srcRaw=getBestSourcePhoneValue();
    var srcDigits=getLocalPhoneDigits(srcRaw);
    if(!srcDigits){lastSrcDigits='';return;}
    if(srcDigits===lastSrcDigits&&srcDigits===getLocalPhoneDigits(uiPh.value))return;
    lastSrcDigits=srcDigits;
