    init.age=String((document.getElementById('ageInput')||{}).value||'').trim();
    init.phones=getUiPhonesForCustomerSave().slice();
    init.phone=init.phones[0]||'';
    var cityVal=String((document.getElementById('addrCity')||{}).value||((document.getElementById('addrCityInput')||{}).dataset||{}).cityId||'').trim();
    if(!init.city||typeof init.city!=='object')init.city={};
