    init.address={
      locality:String((document.getElementById('addrLocality')||{}).value||'').trim(),
      street:String((document.getElementById('addrStreet')||{}).value||'').trim(),
      house:String((document.getElementById('addrHouse')||{}).value||'').trim(),
      office:String(getOfficeValueForBridge()||'').trim(),
      entrance:String((document.getElementById('addrEntrance')||{}).value||'').trim(),
      floor:String((document.getElementById('addrFloor')||{}).value||'').trim(),
      intercom:getUiIntercomState()||''
    };
