function bindCreateCustomerUpdateTouchTracker(){
  try{
    if(!getCreateCustomerId())return;
    if(window.__tmCreateCustomerUpdateTouchTrackerBound)return;
    window.__tmCreateCustomerUpdateTouchTrackerBound=true;
    window.__tmCreateCustomerUpdateTouched=false;
    window.__tmCreateCustomerUpdateTouchSeq=0;
    function isCustomerFieldTarget(target){
      if(!target||!target.closest)return false;
      return !!target.closest(
        '#nameInput,#ageInput,#phList input.phone-short,#addPhoneBtn,#phoneRemoveBtn,'+
        '#addrLocality,#addrStreet,#addrHouse,#addrOffice,#addrEntrance,#addrFloor,'+
        '#dmfInp,#dmfNo,#dmfYes'
      );
    }
    function mark(e){
      if(!e||!e.isTrusted)return;
      if(!isCustomerFieldTarget(e.target))return;
      try{
        var addressField=e.target&&e.target.closest?e.target.closest('#addrLocality,#addrStreet,#addrHouse,#addrOffice,#addrEntrance,#addrFloor'):null;
        if(addressField)addressField.dataset.tmCreateCustomerEdited='1';
      }catch(_markAddressField){}
      window.__tmCreateCustomerUpdateTouched=true;
      window.__tmCreateCustomerUpdateTouchSeq=(Number(window.__tmCreateCustomerUpdateTouchSeq)||0)+1;
    }
    document.addEventListener('input',mark,true);
    document.addEventListener('change',mark,true);
    document.addEventListener('click',mark,true);
  }catch(_){}
}
function refreshCustomerUpdateBaselineAfterAutoHydrate(){
  try{
    bindCreateCustomerUpdateTouchTracker();
    if(!getCreateCustomerId())return;
    if(window.__tmCreateCustomerUpdateTouched)return;
    refreshCustomerUpdateCompareBaselineFromUi();
  }catch(_){}
}
