function ensureAddressHydrationGuard(){
  if(window.__tmAddressHydrationGuardTimer)return;
  var attempts=0;
  window.__tmAddressHydrationGuardTimer=setInterval(function(){
    attempts++;
    var snap=window.__tmLastHydratedCustomerSnapshot;
    if(!snap){if(attempts>12){clearInterval(window.__tmAddressHydrationGuardTimer);window.__tmAddressHydrationGuardTimer=null;}return;}
    var needsRepair=false;
    var addr=snap.address||{};
    var map=[['addrLocality','locality'],['addrStreet','street'],['addrHouse','house'],['addrOffice','office'],['addrEntrance','entrance'],['addrFloor','floor']];
    for(var i=0;i<map.length;i++){
      var id=map[i][0],key=map[i][1];
      var must=String(addr[key]||'').trim();
      if(!must)continue;
      var el=document.getElementById(id);
      if(el&&el.dataset&&el.dataset.tmCreateCustomerEdited==='1')continue;
      if(el&&!String(el.value||'').trim()){needsRepair=true;break;}
    }
    if(needsRepair){
      tmRunPreservingCreateColumnScroll(function(){applyCustomerUpdateSnapshotToUi(snap);});
      refreshCustomerUpdateBaselineAfterAutoHydrate();
    }
    if(attempts>12){clearInterval(window.__tmAddressHydrationGuardTimer);window.__tmAddressHydrationGuardTimer=null;}
  },500);
}
function hydrateClientAndAddressFromCustomerUpdate(){
  var customerId=getCreateCustomerId();
  if(!customerId)return;
  bindCreateCustomerUpdateTouchTracker();
  if(window.__tmCustomerUpdateHydrationDone===customerId)return;
  if(window.__tmCustomerUpdateHydrationPending===customerId)return;
  window.__tmCustomerUpdateHydrationPending=customerId;
  fetchCustomerUpdateSnapshot(customerId).then(function(snap){
    window.__tmLastHydratedCustomerSnapshot=snap;
    tmRunPreservingCreateColumnScroll(function(){applyCustomerUpdateSnapshotToUi(snap);});
    refreshCustomerUpdateBaselineAfterAutoHydrate();
    ensureAddressHydrationGuard();
    window.__tmCustomerUpdateHydrationDone=customerId;
  }).catch(function(err){
    console.warn('[CRM v11] customer update hydrate failed:',err&&err.message?err.message:err);
  }).finally(function(){
    if(window.__tmCustomerUpdateHydrationPending===customerId)window.__tmCustomerUpdateHydrationPending='';
  });
}
