function tmExtractDuplicatePhoneCustomerId(text){
  try{
    var src=String(text||'').replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim();
    if(!src)return '';
    var low=src.toLowerCase();
    if(low.indexOf('номер')===-1||low.indexOf('телефон')===-1||low.indexOf('использ')===-1)return '';
    var m=src.match(/ID\s*Клиента\s*#?\s*(\d{3,})/i)
      || src.match(/ID\s*клиента\s*[:#№]?\s*(\d{3,})/i)
      || src.match(/Клиент[а]?\s*#\s*(\d{3,})/i);
    return m?String(m[1]||''):'';
  }catch(_){return '';}
}
function tmExtractDuplicatePhoneBusyWithoutId(text){
  try{
    var src=String(text||'').replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim();
    if(!src)return null;
    if(tmExtractDuplicatePhoneCustomerId(src))return null;
    var exact=src.match(/Значение\s*[«"]\s*((?:\+?\s*7|8)[\s(.-]*\d{3}[\s).-]*\d{3}[\s.-]*\d{2}[\s.-]*\d{2})\s*[»"]\s*для\s*[«"]\s*Телефон\s*[»"]\s*уже\s*занято/iu);
    if(!exact)return null;
    var phone=tmFormatNoticePhone(exact[1]||'');
    if(String(phone||'').replace(/\D/g,'').length!==11)return null;
    return {
      text:src,
      phone:phone
    };
  }catch(_){return null;}
}
function tmExtractPhoneFromDuplicateBusyText(text){
  try{
    var src=String(text||'');
    var m=src.match(/(?:\+?\s*7|8)[\s(.-]*\d{3}[\s).-]*\d{3}[\s.-]*\d{2}[\s.-]*\d{2}/);
    if(!m)return '';
    return tmFormatNoticePhone(m[0]);
  }catch(_){return '';}
}
function tmFormatNoticePhone(raw){
  try{
    var d=String(raw||'').replace(/\D/g,'');
    if(d.length===11&&(d[0]==='7'||d[0]==='8'))d='7'+d.slice(1);
    if(d.length===10)d='7'+d;
    if(d.length===11&&d[0]==='7')return '+7 '+d.slice(1,4)+'-'+d.slice(4,7)+'-'+d.slice(7,9)+'-'+d.slice(9,11);
    return String(raw||'').trim();
  }catch(_){return String(raw||'').trim();}
}
function tmGetCurrentCreatePrimaryPhoneForNotice(){
  try{
    var candidates=[
      document.querySelector('#phList .ph-item input.phone-short:not(.phone-hidden)'),
      document.querySelector('#customer-phone'),
      document.querySelector('input[name="Customer[phone]"]')
    ];
    for(var i=0;i<candidates.length;i++){
      var el=candidates[i];
      var v=el&&String(el.value||'').trim();
      if(v&&/\d{10,}/.test(v.replace(/\D/g,'')))return tmFormatNoticePhone(v);
    }
  }catch(_){}
  return '';
}
