    box.querySelector('.tm-dup-phone-notice-text').textContent='База вернула ошибку: этот номер телефона уже используется. ID клиента #'+customerId+'.';
    var a=box.querySelector('.tm-dup-phone-notice-link');
    a.style.display='';
    a.href=url;
    a.textContent='Открыть карточку клиента #'+customerId;
