    document.addEventListener('click',function(e){
      var t=e&&e.target;
      if(t&&t.closest&&t.closest('.tm-dup-phone-notice-close')){
        try{e.preventDefault();e.stopPropagation();}catch(_){}
        tmCloseDuplicatePhoneCustomerNotice();
      }
    },true);
