function copyTextToClipboard(text){
  text=String(text||'').trim();
  if(!text)return Promise.reject(new Error('empty'));
  function fallback(){
    var ta=document.createElement('textarea');
    ta.value=text;
    ta.setAttribute('readonly','');
    ta.style.cssText='position:fixed;left:-9999px;top:-9999px;opacity:0;pointer-events:none;';
    document.body.appendChild(ta);
    ta.select();
    ta.setSelectionRange(0,ta.value.length);
    var ok=false;
    try{ok=document.execCommand('copy');}catch(_){}
    if(ta.parentNode)ta.parentNode.removeChild(ta);
    return ok?Promise.resolve():Promise.reject(new Error('copy failed'));
  }
  try{
    if(typeof GM_setClipboard==='function'){
      GM_setClipboard(text,'text');
      return Promise.resolve();
    }
  }catch(_){}
  try{
    if(navigator.clipboard&&navigator.clipboard.writeText){
      return navigator.clipboard.writeText(text).catch(fallback);
    }
  }catch(_){}
  return fallback();
}
function installClientRegionCopy(holder){
  if(!holder||holder.dataset.tmRegionCopyBound==='1')return;
  holder.dataset.tmRegionCopyBound='1';
  holder.setAttribute('role','button');
  holder.setAttribute('tabindex','0');
  holder.setAttribute('aria-label','Скопировать область');
  function clearRegionPress(){
    try{holder.classList.remove('tm-region-pressing');}catch(_){}
  }
  function copyRegion(){
    var text=String(holder.textContent||'').replace(/\s+/g,' ').trim();
    if(!text||text==='—'){clearRegionPress();return;}
    copyTextToClipboard(text).then(function(){
      clearRegionPress();
      holder.classList.add('tm-region-copied');
      clearTimeout(holder.__tmRegionCopiedTimer);
      holder.__tmRegionCopiedTimer=setTimeout(function(){
        holder.classList.remove('tm-region-copied');
      },420);
    }).catch(function(){clearRegionPress();});
  }
  holder.addEventListener('pointerdown',function(e){
    holder.classList.add('tm-region-pressing');
    e.preventDefault();
  });
  holder.addEventListener('pointerup',function(){setTimeout(clearRegionPress,90);});
  holder.addEventListener('pointercancel',clearRegionPress);
  holder.addEventListener('mouseleave',clearRegionPress);
  holder.addEventListener('click',copyRegion);
  holder.addEventListener('keydown',function(e){
    if(e.key!=='Enter'&&e.key!==' ')return;
    e.preventDefault();
    copyRegion();
  });
}
function getTelegramUrlAtTextPosition(text,position){
  text=String(text||'');
  position=Math.max(0,Number(position)||0);
  var re=/https?:\/\/(?:www\.)?(?:t\.me|telegram\.me)\/[^\s<>"']+/gi;
  var match;
  while((match=re.exec(text))){
    var url=match[0].replace(/[.,;:!?)}\]]+$/,'');
    var start=match.index;
    var end=start+url.length;
    if(position>=start&&position<=end)return url;
  }
  return '';
}
function installServiceCommentTelegramCopy(textarea){
  if(!textarea||textarea.dataset.tmTelegramCopyBound==='1')return;
  textarea.dataset.tmTelegramCopyBound='1';
  textarea.addEventListener('click',function(){
    if(textarea.selectionStart!==textarea.selectionEnd)return;
    var position=textarea.selectionStart;
    var url=getTelegramUrlAtTextPosition(textarea.value,position);
    if(!url)return;
    copyTextToClipboard(url).then(function(){
      showToast('Ссылка Telegram скопирована');
    }).catch(function(){
      showToast('Не удалось скопировать ссылку');
    });
  });
}
function flashCopiedPhone(wrap,input){
  if(!wrap)return;
  wrap.classList.remove('tm-phone-copy-failed');
  wrap.classList.add('tm-phone-copied');
  updatePhoneCopyVisual(wrap,input);
  clearTimeout(wrap.__tmPhoneCopiedTimer);
  wrap.__tmPhoneCopiedTimer=setTimeout(function(){
    try{wrap.classList.remove('tm-phone-copied');}catch(_){}
    updatePhoneCopyVisual(wrap,input);
  },1320);
}
function updatePhoneCopyVisual(wrap,input){
  try{
    if(!wrap)return;
    input=input||(wrap.querySelector&&wrap.querySelector('.phone-short'));
    if(!input)return;
    var dark=!!(document.documentElement&&document.documentElement.classList.contains('tm-v11-dark'));
    var active=!!(wrap.classList&&(wrap.classList.contains('tm-phone-pressing')||wrap.classList.contains('tm-phone-copied')));
    input.classList.toggle('tm-phone-pressing',dark&&wrap.classList.contains('tm-phone-pressing'));
    input.classList.toggle('tm-phone-copied',dark&&wrap.classList.contains('tm-phone-copied'));
    if(dark&&active){
      input.style.setProperty('color','#5B97CC','important');
      input.style.setProperty('-webkit-text-fill-color','#5B97CC','important');
      input.style.setProperty('text-shadow','0 0 1px rgba(91,151,204,.14)','important');
    }else{
      input.classList.remove('tm-phone-pressing','tm-phone-copied');
      input.style.removeProperty('color');
      input.style.removeProperty('-webkit-text-fill-color');
      input.style.removeProperty('text-shadow');
    }
  }catch(_){}
}
function installCallablePhoneCopy(wrap,input,copyText){
  if(!wrap||!input)return;
  wrap.classList.add('tm-phone-copy-ready');
  wrap.dataset.tmCopyPhone=String(copyText||input.value||'').trim();
  wrap.title='Скопировать номер';
  input.title='Скопировать номер';
  try{
    wrap.style.setProperty('cursor','pointer','important');
    input.style.setProperty('cursor','pointer','important');
  }catch(_){}
  if(wrap.dataset.tmCopyPhoneInstalled==='1')return;
  wrap.dataset.tmCopyPhoneInstalled='1';
  wrap.addEventListener('mousedown',function(e){
    if(e&&e.button===0){
      e.preventDefault();
      wrap.classList.add('tm-phone-pressing');
      updatePhoneCopyVisual(wrap,input);
      clearTimeout(wrap.__tmPhonePressTimer);
      wrap.__tmPhonePressTimer=setTimeout(function(){try{wrap.classList.remove('tm-phone-pressing');}catch(_){} updatePhoneCopyVisual(wrap,input);},180);
    }
  },true);
  ['mouseup','mouseleave','blur'].forEach(function(ev){
    wrap.addEventListener(ev,function(){
      clearTimeout(wrap.__tmPhonePressTimer);
      wrap.__tmPhonePressTimer=setTimeout(function(){try{wrap.classList.remove('tm-phone-pressing');}catch(_){} updatePhoneCopyVisual(wrap,input);},60);
    },true);
  });
  wrap.addEventListener('click',function(e){
    var text=String(wrap.dataset.tmCopyPhone||input.value||'').trim();
    if(!text)return;
    if(e){e.preventDefault();e.stopPropagation();}
    copyTextToClipboard(text).then(function(){
      flashCopiedPhone(wrap,input);
    }).catch(function(){
      try{showToast('Не удалось скопировать номер');}catch(_){}
    });
  },true);
  input.addEventListener('keydown',function(e){
    var k=String(e&&e.key||'');
    if(k!=='Enter'&&k!==' ')return;
    e.preventDefault();
    var text=String(wrap.dataset.tmCopyPhone||input.value||'').trim();
    if(!text)return;
    copyTextToClipboard(text).then(function(){
      flashCopiedPhone(wrap,input);
    }).catch(function(){
      try{showToast('Не удалось скопировать номер');}catch(_){}
    });
  });
}
function rememberMapOpenMods(evt){
  var mods={
    ctrl:!!(evt&&evt.ctrlKey),
    meta:!!(evt&&evt.metaKey),
    shift:!!(evt&&evt.shiftKey),
    alt:!!(evt&&evt.altKey)
  };
  window.__tmMapOpenMods=mods;
  return mods;
}
function dispatchMapBtnClickWithMods(btn,mods){
  if(!btn)return;
  var m=mods||window.__tmMapOpenMods||{};
  var dw=(btn.ownerDocument&&btn.ownerDocument.defaultView)||window;
  try{dw.__tmForceMapCtrlMode=!!(m.ctrl||m.meta);}catch(_e){}
  try{
    var EvtCtor=dw.MouseEvent||MouseEvent;
    var ev=new EvtCtor('click',{
      bubbles:true,
      cancelable:true,
      view:dw,
      ctrlKey:!!m.ctrl,
      metaKey:!!m.meta,
      shiftKey:!!m.shift,
      altKey:!!m.alt
    });
    btn.dispatchEvent(ev);
  }catch(e){
    btn.click();
  }
}
function openAddressMap(evtOrAttempt,maybeAttempt){
  var attempt=0;
  if(typeof evtOrAttempt==='number'){
    attempt=Number(evtOrAttempt)||0;
  }else{
    attempt=Number(maybeAttempt)||0;
    rememberMapOpenMods(evtOrAttempt||null);
  }
  if(attempt===0&&!isCitySelectedUi()){showToast('Сначала выберите город');return;}
  if(attempt===0){window.__tmV11AddressForMap={locality:(document.getElementById('addrLocality')&&document.getElementById('addrLocality').value||'').trim(),street:(document.getElementById('addrStreet')&&document.getElementById('addrStreet').value||'').trim(),house:(document.getElementById('addrHouse')&&document.getElementById('addrHouse').value||'').trim(),ts:Date.now()};}
  try{
    var doc=getBridgeDoc();
    if(!doc){if(attempt<8)setTimeout(function(){openAddressMap(attempt+1);},120);return;}
    var btn=doc.getElementById('open-map-btn');
    if(!btn){if(attempt<8)setTimeout(function(){openAddressMap(attempt+1);},120);else alert('Кнопка карты не найдена');return;}
    dispatchMapBtnClickWithMods(btn,window.__tmMapOpenMods||null);
  }catch(e){if(attempt<6)setTimeout(function(){openAddressMap(attempt+1);},140);}
}
function ensureCityOptionsFromBridge(doc){
  var ui=document.getElementById('addrCity');if(!ui||!doc)return;
  var src=doc.getElementById('customerrequest-city_id');if(!src||!src.options)return;
  var cityInputPre=document.getElementById('addrCityInput');
  var cityBtnPre=document.getElementById('addrCityBtnText');
  var preUiVal=String(ui.value||'').trim();
  var preCityId=cityInputPre&&cityInputPre.dataset?String(cityInputPre.dataset.cityId||'').trim():'';
  var preInputText=cityInputPre?String(cityInputPre.value||'').trim():'';
  var preBtnText=cityBtnPre?String(cityBtnPre.textContent||'').trim():'';
  var currentSrcVal=String(src.value||'').trim();
  var lockUntil=Number(window.__tmCityManualPickUntil||0);
  var lockActive=Date.now()<lockUntil;
  var keepCityId=preCityId||preUiVal;
  var preserveUiCity=!!keepCityId&&(!currentSrcVal||lockActive);
  var effectiveVal=preserveUiCity?keepCityId:currentSrcVal;
  var key=String(src.options.length)+':'+String(preserveUiCity?effectiveVal:(src.options[src.selectedIndex]?src.options[src.selectedIndex].value:''));
  if(ui.dataset.srcKey===key&&ui.dataset.optionsReady==='1')return;
  ui.innerHTML='';
  for(var i=0;i<src.options.length;i++){
    var o=src.options[i];
    var op=document.createElement('option');
    op.value=o.value||'';
    op.textContent=(o.text||'').trim()||'Выберите город';
    ui.appendChild(op);
  }
  if(!ui.options.length){
    var fallback=document.createElement('option');
    fallback.value='';
    fallback.textContent='Выберите город';
    ui.appendChild(fallback);
  }
  ui.value=effectiveVal;
  if(ui.value!==effectiveVal&&effectiveVal){
    var ext=document.createElement('option');
    ext.value=effectiveVal;
    ext.textContent=(src.options[src.selectedIndex]&&src.options[src.selectedIndex].text||effectiveVal).trim();
    ui.appendChild(ext);
    ui.value=effectiveVal;
  }
  ui.dataset.optionsReady='1';
  ui.dataset.srcKey=key;
  var cityInput=document.getElementById('addrCityInput');
  var cityBtnLabel=document.getElementById('addrCityBtnText');
  if(cityInput){
    var srcText=(src.options[src.selectedIndex]&&src.options[src.selectedIndex].text||'').trim();
    if(srcText==='Выберите город')srcText='';
    if(preserveUiCity&&!currentSrcVal){
      var keepText=preInputText||((preBtnText&&preBtnText!=='Выберите')?preBtnText:'');
      cityInput.dataset.cityId=effectiveVal||'';
      if(keepText&&(document.activeElement!==cityInput||!(cityInput.value||'').trim()))cityInput.value=keepText;
      if(cityBtnLabel){
        cityBtnLabel.textContent=keepText||'Выберите';
        if(keepText){cityBtnLabel.classList.remove('ph');}else{cityBtnLabel.classList.add('ph');}
      }
      syncLegacyCityAliasForStatusBadge();
      return;
    }
    cityInput.dataset.cityId=effectiveVal||'';
    if(document.activeElement!==cityInput||!(cityInput.value||'').trim())cityInput.value=srcText;
  }
  if(cityBtnLabel&&!cityInput){
    var srcText2=(src.options[src.selectedIndex]&&src.options[src.selectedIndex].text||'').trim();
    if(srcText2==='Выберите город')srcText2='';
    cityBtnLabel.textContent=srcText2||'Выберите';
    if(srcText2){cityBtnLabel.classList.remove('ph');}else{cityBtnLabel.classList.add('ph');}
  }
  syncLegacyCityAliasForStatusBadge();
}
function getNativeCitySnapshotForStatusBadge(){
  var cityId=String((document.getElementById('addrCity')||{}).value||'').trim()
    ||String((((document.getElementById('addrCityInput')||{}).dataset)||{}).cityId||'').trim();
  var scopes=[];
  if(window.__tmNativeRequestForm&&window.__tmNativeRequestForm.querySelector)scopes.push(window.__tmNativeRequestForm);
  var holder=document.getElementById('tmCrmFormHolder');
  if(holder&&holder.querySelector)scopes.push(holder);
  scopes.push(document);
  var selectEl=null;
  var text='';
  for(var si=0;si<scopes.length;si++){
    var sc=scopes[si];
    if(!sc||!sc.querySelector)continue;
    var cand=sc.querySelector('#customerrequest-city_id, select[name="CustomerRequest[city_id]"]');
    if(!cand)continue;
    if(!selectEl)selectEl=cand;
    if(cityId&&String(cand.value||'').trim()!==cityId)cand.value=cityId;
    if(cand.options&&cand.options.length){
      if(cityId){
        for(var oi=0;oi<cand.options.length;oi++){
          var opt=cand.options[oi];
          if(String(opt&&opt.value||'').trim()===cityId){
            text=String(opt&&opt.text||'').trim();
            break;
          }
        }
      }
      if((!text||text==='Выберите'||text==='Выберите город')&&cand.selectedIndex>=0){
        text=String((cand.options[cand.selectedIndex]&&cand.options[cand.selectedIndex].text)||'').trim();
      }
    }
    if(text&&text!=='Выберите'&&text!=='Выберите город')break;
  }
  if(text==='Выберите'||text==='Выберите город')text='';
  return {cityId:cityId,cityText:text,selectEl:selectEl};
}
function getUiCityLabelForStatusBadge(){
  var snap=getNativeCitySnapshotForStatusBadge();
  var cityId=String((snap&&snap.cityId)||'').trim();
  var label=String((snap&&snap.cityText)||'').trim();
  var uiSel=document.getElementById('addrCity');
  if((!label||label==='Выберите')&&uiSel&&uiSel.options&&uiSel.options.length){
    if(cityId){
      for(var i=0;i<uiSel.options.length;i++){
        var o=uiSel.options[i];
        if(String(o&&o.value||'').trim()===cityId){
          label=String(o&&o.text||'').trim();
          break;
        }
      }
    }
    if((!label||label==='Выберите')&&uiSel.selectedIndex>=0){
      label=String((uiSel.options[uiSel.selectedIndex]&&uiSel.options[uiSel.selectedIndex].text)||'').trim();
    }
  }
  if(!label||label==='Выберите'){
    label=String((document.getElementById('addrCityBtnText')||{}).textContent||'').trim();
  }
  if(label==='Выберите')label='';
  return label;
}
function syncLegacyCityAliasForStatusBadge(){
  try{
    var snap=getNativeCitySnapshotForStatusBadge();
    var cityId=String((snap&&snap.cityId)||'').trim();
    var cityText=String((snap&&snap.cityText)||'').trim()||getUiCityLabelForStatusBadge();
    var nativeScopes=[];
    if(window.__tmNativeRequestForm&&window.__tmNativeRequestForm.querySelector){
      nativeScopes.push(window.__tmNativeRequestForm);
    }
    var holder=document.getElementById('tmCrmFormHolder');
    if(holder){
      nativeScopes.push(holder);
    }
    nativeScopes.push(document);
    var legacySelect=null;
    var nativeCityText='';
    for(var si=0;si<nativeScopes.length;si++){
      var sc=nativeScopes[si];
      if(!sc||!sc.querySelector)continue;
      var cand=sc.querySelector('#customerrequest-city_id, select[name="CustomerRequest[city_id]"]');
      if(!cand)continue;
      if(cityId&&String(cand.value||'').trim()!==cityId)cand.value=cityId;
      if(!nativeCityText&&cand.options&&cand.options.length){
        if(cityId){
          for(var oi=0;oi<cand.options.length;oi++){
            var opt=cand.options[oi];
            if(String(opt&&opt.value||'').trim()===cityId){
              nativeCityText=String(opt&&opt.text||'').trim();
              break;
            }
          }
        }
        if((!nativeCityText||nativeCityText==='Выберите')&&cand.selectedIndex>=0){
          nativeCityText=String((cand.options[cand.selectedIndex]&&cand.options[cand.selectedIndex].text)||'').trim();
        }
      }
      if(!legacySelect)legacySelect=cand;
    }
    if(nativeCityText&&nativeCityText!=='Выберите'&&nativeCityText!=='Выберите город')cityText=nativeCityText;
    if((!cityText||cityText==='Выберите')&&legacySelect&&legacySelect.options&&legacySelect.selectedIndex>=0){
      cityText=String((legacySelect.options[legacySelect.selectedIndex]&&legacySelect.options[legacySelect.selectedIndex].text)||'').trim();
    }
    var labels=Array.from(document.querySelectorAll('#select2-customerrequest-city_id-container'));
    if(!cityText||cityText==='Выберите'||cityText==='Выберите город'){
      for(var ci=0;ci<labels.length;ci++){
        var clearLb=labels[ci];
        if(clearLb&&clearLb.textContent)clearLb.textContent='';
      }
      return;
    }
    if(!labels.length){
      var host2=document.getElementById('tmCrmFormHolder')||document.body||document.documentElement;
      if(host2){
        var legacyLabel=document.createElement('span');
        legacyLabel.id='select2-customerrequest-city_id-container';
        legacyLabel.style.cssText='position:fixed;left:-10000px;top:-10000px;opacity:0;pointer-events:none;white-space:nowrap;';
        host2.appendChild(legacyLabel);
        labels.push(legacyLabel);
      }
    }
    for(var li=0;li<labels.length;li++){
      var lb=labels[li];
      if(lb&&String(lb.textContent||'').trim()!==cityText)lb.textContent=cityText;
    }
  }catch(_e){}
}
function markCityManualChoice(ttlMs){
  var ttl=Math.max(1000,Number(ttlMs)||15000);
  window.__tmCityManualPickUntil=Date.now()+ttl;
}
function rememberPendingCityChoice(cityId,cityText){
  var id=String(cityId||'').trim();
  if(!id)return;
  var txt=String(cityText||'').trim();
  window.__tmPendingCityPush={
    id:id,
    text:txt,
    at:Date.now(),
    until:Date.now()+20000,
    lastTry:0
  };
}
function ensureBridgeCityOption(src,cityId,cityText){
  if(!src)return false;
  var id=String(cityId||'').trim();
  if(!id)return false;
  var has=false;
  try{
    for(var i=0;i<(src.options?src.options.length:0);i++){
      if(String(src.options[i].value||'').trim()===id){has=true;break;}
    }
    if(!has){
      var op=(src.ownerDocument||document).createElement('option');
      op.value=id;
      op.textContent=String(cityText||id).trim()||id;
      src.appendChild(op);
    }
  }catch(_e){}
  return true;
}
function isCustomerRequestCityField(field){
  try{
    var key=String((field&&field.id||'')+' '+(field&&field.name||'')).toLowerCase();
    return key.indexOf('customerrequest')!==-1&&key.indexOf('city_id')!==-1;
  }catch(_){return false;}
}
function emitBridgeCitySelecting(selectEl,cityId,cityText,winRef){
  try{
    if(!selectEl||!isCustomerRequestCityField(selectEl))return;
    var w=winRef||window;
    if(w&&w.$&&w.$(selectEl).length){
      var data={id:String(cityId||''),text:String(cityText||cityId||'')};
      w.$(selectEl).trigger({type:'select2:selecting',params:{args:{data:data},data:data}});
    }
  }catch(_e){}
}
function applyBridgeCityValueToField(field,cityId,cityText,frameWin,force){
  if(!field)return false;
  var id=String(cityId||'').trim();
  if(!id)return false;
  var changed=false;
  try{
    var tag=String(field.tagName||'').toLowerCase();
    if(tag==='select'){
      ensureBridgeCityOption(field,id,cityText);
    }
    if(String(field.value||'').trim()!==id){
      emitBridgeCitySelecting(field,id,cityText,frameWin);
      field.value=id;
      changed=true;
    }
    if(changed){
      emitBridgeSelectEvents(field,frameWin);
    }
  }catch(_e){}
  return changed;
}
function applyCityToBridgeCityFields(doc,cityId,cityText,frameWin,force){
  if(!doc)return {changed:false,count:0};
  var id=String(cityId||'').trim();
  if(!id)return {changed:false,count:0};
  var keepCustomerCity=tmShouldKeepCustomerCardCityUntouched();
  var selectors=[
    '#customerrequest-city_id',
    'select[name="CustomerRequest[city_id]"]',
    'input[name="CustomerRequest[city_id]"]'
  ];
  if(!keepCustomerCity){
    selectors=selectors.concat([
      '#customer-city_id',
      'select[name="Customer[city_id]"]',
      'input[name="Customer[city_id]"]',
      'select[id*="city_id"]',
      'input[id*="city_id"]',
      'select[name*="[city_id]"]',
      'input[name*="[city_id]"]'
    ]);
  }
  var seen=[];
  var changed=false;
  var count=0;
  try{
    Array.from(doc.querySelectorAll(selectors.join(','))).forEach(function(field){
      if(!field||seen.indexOf(field)!==-1)return;
      seen.push(field);
      var meta=String((field.id||'')+' '+(field.name||'')).toLowerCase();
      if(meta.indexOf('city_id')===-1)return;
      if(keepCustomerCity&&meta.indexOf('customerrequest')===-1)return;
      count++;
      if(applyBridgeCityValueToField(field,id,cityText,frameWin,force))changed=true;
    });
  }catch(_e){}
  return {changed:changed,count:count};
}
function tryFlushPendingCityChoice(){
  var p=window.__tmPendingCityPush;
  if(!p)return;
  var now=Date.now();
  if(now>Number(p.until||0)){window.__tmPendingCityPush=null;return;}
  var doc=getBridgeDoc();
  var src=doc&&doc.getElementById('customerrequest-city_id');
  if(src&&String(src.value||'').trim()===String(p.id||'')){
    window.__tmPendingCityPush=null;
    return;
  }
  if(now-Number(p.lastTry||0)<140)return;
  p.lastTry=now;
  syncCityToBridge(true);
}
function syncCityFromBridge(){
  try{
    var doc=getBridgeDoc();if(!doc)return;
    ensureCityOptionsFromBridge(doc);
    var ui=document.getElementById('addrCity');var src=doc.getElementById('customerrequest-city_id');
    if(!ui||!src)return;
    var uiVal=String(ui.value||'').trim();
    var srcVal=String(src.value||'').trim();
    var pending=window.__tmPendingCityPush;
    if(pending&&srcVal&&srcVal===String(pending.id||''))window.__tmPendingCityPush=null;
    var lockUntil=Number(window.__tmCityManualPickUntil||0);
    var lockActive=Date.now()<lockUntil;
    // Не затираем непустой выбор пользователя пустым/запаздывающим значением bridge.
    var keepUiCity=!!uiVal&&(!srcVal||lockActive);
    if(keepUiCity&&uiVal!==srcVal){
      var _now=Date.now();
      var _last=Number(window.__tmCityBridgeResyncAt||0);
      if(!_last||(_now-_last)>220){
        window.__tmCityBridgeResyncAt=_now;
        syncCityToBridge(true);
      }
      updateTimeControlsByCity();
      tick();
      return;
    }
    if(uiVal!==srcVal)ui.value=srcVal||'';
    var cityInput=document.getElementById('addrCityInput');
    var cityBtnLabel=document.getElementById('addrCityBtnText');
    if(cityInput||cityBtnLabel){
      var srcText=(src.options[src.selectedIndex]&&src.options[src.selectedIndex].text||'').trim();
      if(srcText==='Выберите город')srcText='';
      if(cityInput){cityInput.value=srcText||'';cityInput.dataset.cityId=src.value||'';}
      if(cityBtnLabel){
        cityBtnLabel.textContent=srcText||'Выберите';
        if(srcText){cityBtnLabel.classList.remove('ph');}else{cityBtnLabel.classList.add('ph');}
      }
    }
    syncLegacyCityAliasForStatusBadge();
    updateTimeControlsByCity();
    tick();
  }catch(e){}
}
function warmupAppTypeAfterCitySelect(){
  if(window.__cityTechWarmupBusy)return;
  var appInp=document.getElementById('appTypeInput');
  if(!appInp)return;
  window.__cityTechWarmupBusy=true;
  try{appInp.focus({preventScroll:true});}catch(_e){try{appInp.focus();}catch(_e2){}}
  setTimeout(function(){
    try{appInp.blur();}catch(_e){}
    window.__cityTechWarmupBusy=false;
  },0);
}
function emitBridgeSelectEvents(selectEl,winRef){
  if(!selectEl)return;
  var isCity=isCustomerRequestCityField(selectEl);
  if(!isCity){
    try{selectEl.dispatchEvent(new Event('input',{bubbles:true}));}catch(_e1){}
  }
  try{selectEl.dispatchEvent(new Event('change',{bubbles:true}));}catch(_e2){}
  try{
    var w=winRef||window;
    if(w&&w.$&&w.$(selectEl).length){
      var $el=w.$(selectEl);
      if(!isCity)$el.trigger('input');
      $el.trigger('change');
      if(isCity){
        var opt=selectEl.options&&selectEl.options[selectEl.selectedIndex];
        var data={id:String(selectEl.value||''),text:String(opt&&opt.text||selectEl.value||'')};
        $el.trigger({type:'select2:select',params:{data:data}});
      }
      $el.trigger('change.select2');
    }
  }catch(_e3){}
}
function isBridgeElementVisible(el,winRef){
  try{
    if(!el||!el.isConnected)return false;
    var w=winRef||(el.ownerDocument&&el.ownerDocument.defaultView)||window;
    var cs=w.getComputedStyle?w.getComputedStyle(el):null;
    if(cs&&(cs.display==='none'||cs.visibility==='hidden'))return false;
    var r=el.getBoundingClientRect?el.getBoundingClientRect():null;
    if(r&&(r.width<=0||r.height<=0))return false;
    return true;
  }catch(_){return false;}
}
function fireBridgeMouseClick(el,winRef){
  return tmSingleProgrammaticClick(el,700);
}
function ensureBridgeNewCustomerOpen(doc,frameWin){
  if(!doc)return false;
  try{
    var block=doc.getElementById('newCustomer');
    var toggler=doc.getElementById('newCustomerToggler');
    var saveAction=doc.getElementById('newCustomerSaveAction');
    var blockOpen=saveAction?isBridgeElementVisible(saveAction,frameWin):(block?isBridgeElementVisible(block,frameWin):false);
    if(!blockOpen&&toggler){
      var w=frameWin||(doc.defaultView||window);
      var now=Date.now();
      if(w&&w.__tmNewCustomerOpenRequestedAt&&now-Number(w.__tmNewCustomerOpenRequestedAt)<850)return true;
      if(w)w.__tmNewCustomerOpenRequestedAt=now;
      if(toggler.classList)toggler.classList.remove('disabled');
      fireBridgeMouseClick(toggler,frameWin);
      return true;
    }
  }catch(_){}
  return false;
}
function syncCityToBridge(force){
  try{
    var ui=document.getElementById('addrCity');
    var cityInput=document.getElementById('addrCityInput');
    if(cityInput&&cityInput.dataset&&cityInput.dataset.cityId&&ui&&(ui.value||'')!==cityInput.dataset.cityId)ui.value=cityInput.dataset.cityId;
    var targetCity=String((ui&&ui.value)||((cityInput&&cityInput.dataset&&cityInput.dataset.cityId)||'')||'').trim();
    var targetText=String((cityInput&&cityInput.value)||'').trim()||String((document.getElementById('addrCityBtnText')||{}).textContent||'').trim();
    if(targetText==='Выберите')targetText='';
    if(targetCity)rememberPendingCityChoice(targetCity,targetText);
    var doc=getBridgeDoc();
    if(!doc){
      if(targetCity){
        try{
          if(typeof __startRegionBridgeNow==='function')__startRegionBridgeNow(false);
          else if(typeof initRegionBridge==='function')initRegionBridge();
        }catch(_boot){}
        if(!window.__tmCityBridgeBootRetry){
          window.__tmCityBridgeBootRetry=1;
          setTimeout(function(){window.__tmCityBridgeBootRetry=0;try{syncCityToBridge(true);}catch(_e){}},180);
        }
      }
      return;
    }
    var frameWin=getBridgeWin();
    if(!targetCity)return;
    var src=doc.getElementById('customerrequest-city_id')||doc.querySelector('select[name="CustomerRequest[city_id]"],input[name="CustomerRequest[city_id]"]');
    var wasCitySelected=!!(src&&String(src.value||'').trim());
    var sameCity=true;
    if(src){
      sameCity=(String(src.value||'').trim()===targetCity);
      if(!sameCity){
        armCityChangeTimeReasonAutoConfirm(targetCity);
        scheduleCityChangeTimeReasonAutoConfirm();
      }
      applyBridgeCityValueToField(src,targetCity,targetText,frameWin,force);
    }
    var allCityResult=applyCityToBridgeCityFields(doc,targetCity,targetText,frameWin,force);
    var keepCustomerCity=tmShouldKeepCustomerCardCityUntouched();
    var customerCity=keepCustomerCity?null:(doc.getElementById('customer-city_id')||doc.querySelector('select[name="Customer[city_id]"],input[name="Customer[city_id]"]'));
    var sameCustomerCity=keepCustomerCity||!customerCity||String(customerCity.value||'').trim()===targetCity;
    var appliedCity=src?String(src.value||'').trim():'';
    var appliedCustomer=customerCity?String(customerCity.value||'').trim():'';
    if(targetCity&&(appliedCity===targetCity||appliedCustomer===targetCity)){
      var p=window.__tmPendingCityPush;
      if(p&&String(p.id||'')===targetCity)window.__tmPendingCityPush=null;
    }
    updateTimeControlsByCity();
    var isCitySelected=!!targetCity;
    if(!wasCitySelected&&isCitySelected)warmupAppTypeAfterCitySelect();
    if(!sameCity||!sameCustomerCity||allCityResult.changed||force){
      try{setTimeout(syncSaveCardState,0);}catch(_e4){}
      try{setTimeout(syncSaveCardState,120);}catch(_e5){}
      try{setTimeout(syncSaveCardState,320);}catch(_e6){}
    }
    if(!sameCity){
      setTimeout(scheduleCityChangeTimeReasonAutoConfirm,40);
      setTimeout(scheduleCityChangeTimeReasonAutoConfirm,180);
      setTimeout(scheduleCityChangeTimeReasonAutoConfirm,420);
    }
    syncLegacyCityAliasForStatusBadge();
  }catch(e){}
}
function switchSpecialCityToAbakanForNotFormalized(){
  try{
    function norm(v){
      return String(v||'').replace(/\s+/g,' ').trim().toLowerCase().replace(/ё/g,'е');
    }
    var current=norm(getUiCityLabelForStatusBadge());
    if(['test','кц','москва','санкт-петербург'].indexOf(current)===-1)return false;

    var ui=document.getElementById('addrCity');
    var bridgeDoc=getBridgeDoc();
    if(bridgeDoc)ensureCityOptionsFromBridge(bridgeDoc);

    var abakanId='';
    var sources=[
      ui,
      bridgeDoc&&(bridgeDoc.getElementById('customerrequest-city_id')||bridgeDoc.querySelector('select[name="CustomerRequest[city_id]"]')),
      document.querySelector('#customerrequest-city_id,select[name="CustomerRequest[city_id]"]')
    ];
    for(var si=0;si<sources.length&&!abakanId;si++){
      var source=sources[si];
      if(!source||!source.options)continue;
      for(var oi=0;oi<source.options.length;oi++){
        var option=source.options[oi];
        if(norm(option&&option.text)==='абакан'){
          abakanId=String(option.value||'').trim();
          break;
        }
      }
    }
    if(!abakanId)return false;

    if(ui){
      ensureBridgeCityOption(ui,abakanId,'Абакан');
      ui.value=abakanId;
    }
    var input=document.getElementById('addrCityInput');
    if(input){
      input.value='Абакан';
      input.dataset.cityId=abakanId;
    }
    var label=document.getElementById('addrCityBtnText');
    if(label){
      label.textContent='Абакан';
      label.classList.remove('ph');
    }
    markCityManualChoice(15000);
    rememberPendingCityChoice(abakanId,'Абакан');
    syncCityToBridge(true);
    syncCreatePrereqLocks();
    stabilizeCityBridgeSync(abakanId);
    return true;
  }catch(_){return false;}
}
function warmSaveCardBridgeSoon(delay){
  return;
}
function stabilizeCityBridgeSync(cityId){
  var target=String(cityId||'').trim();
  if(!target)return;
  var attempts=0;
  (function ensureSync(){
    attempts++;
    try{syncCityToBridge(true);}catch(_e){}
    try{
      var doc=getBridgeDoc();
      var src=doc&&doc.getElementById('customerrequest-city_id');
      var st=doc?getBridgeSaveCardState(doc):null;
      var cityOk=!!src&&String(src.value||'').trim()===target;
      var asksCity=!!(st&&st.asksCity);
      var stateReady=!!(st&&st.active);
      if(cityOk&&(stateReady||!asksCity)){
        try{syncSaveCardState();}catch(_e2){}
        return;
      }
    }catch(_e3){}
    if(attempts<8)setTimeout(ensureSync,120);
  })();
}
