function tmEnsureRequiredBlinkStyle(){
  if(document.getElementById('tm-required-blink-style'))return;
  var style=document.createElement('style');
  style.id='tm-required-blink-style';
  style.textContent='.tm-required-blink{outline:none !important;}html.tm-v11-dark .tm-required-blink{outline:none !important;}';
  document.head.appendChild(style);
}
function tmPulseRequiredBorder(el,token){
  try{
    if(!el||!el.style)return;
    var previous=el.__tmRequiredBorderPulseState;
    if(previous){
      if(previous.borderValue)el.style.setProperty('border-color',previous.borderValue,previous.borderPriority||'');
      else el.style.removeProperty('border-color');
      if(previous.transitionValue)el.style.setProperty('transition',previous.transitionValue,previous.transitionPriority||'');
      else el.style.removeProperty('transition');
    }
    var state={
      borderValue:el.style.getPropertyValue('border-color'),
      borderPriority:el.style.getPropertyPriority('border-color'),
      transitionValue:el.style.getPropertyValue('transition'),
      transitionPriority:el.style.getPropertyPriority('transition')
    };
    el.__tmRequiredBorderPulseState=state;
    el.style.setProperty('transition','none','important');
    var steps=[0,180,360,540,720,900,1080,1260];
    function restore(){
      try{
        if(state.borderValue)el.style.setProperty('border-color',state.borderValue,state.borderPriority||'');
        else el.style.removeProperty('border-color');
      }catch(_){}
    }
    steps.forEach(function(delay,index){
      setTimeout(function(){
        try{
          if(el.dataset&&el.dataset.tmRequiredBlinkToken!==token)return;
          if(index%2===0)el.style.setProperty('border-color','#d83340','important');
          else restore();
        }catch(_){}
      },delay);
    });
    setTimeout(function(){
      try{
        if(el.dataset&&el.dataset.tmRequiredBlinkToken!==token)return;
        restore();
        if(state.transitionValue)el.style.setProperty('transition',state.transitionValue,state.transitionPriority||'');
        else el.style.removeProperty('transition');
        if(el.__tmRequiredBorderPulseState===state)delete el.__tmRequiredBorderPulseState;
      }catch(_){}
    },1400);
  }catch(_){}
}
function tmBlinkRequiredTargets(targets){
  var list=Array.isArray(targets)?targets:[targets];
  tmEnsureRequiredBlinkStyle();
  list.forEach(function(el){
    if(!el)return;
    try{
      var token=String(Date.now())+':'+String(Math.random());
      if(el.dataset)el.dataset.tmRequiredBlinkToken=token;
      el.classList.remove('tm-required-blink');
      requestAnimationFrame(function(){
        requestAnimationFrame(function(){
          try{
            if(el.dataset&&el.dataset.tmRequiredBlinkToken!==token)return;
            el.classList.add('tm-required-blink');
            tmPulseRequiredBorder(el,token);
          }catch(_){}
        });
      });
      setTimeout(function(){
        try{
          if(!el.dataset||el.dataset.tmRequiredBlinkToken!==token)return;
          el.classList.remove('tm-required-blink');
          delete el.dataset.tmRequiredBlinkToken;
        }catch(_){}
      },1450);
    }catch(_){}
  });
}
