function applyPhoneShortInlineWidth(widthPx,targetEl){
  const w=Math.max(72,Math.ceil(Number(widthPx)||0));
  if(!w)return;
  const width=w+'px';
  try{
    window.__tmPhoneShortWidthApplying=true;
    const fields=targetEl?[targetEl]:Array.from(document.querySelectorAll('#phList .phone-short,.tm-mod-phone-readonly-wrap .phone-short,.tm-cu-phone-host-v input.form-control,.tm-cu-phone-host-v textarea.form-control'));
    fields.forEach(function(el){
      try{
        if(el.closest&&el.closest('.tm-cu-phone-host-v')){
          stretchCustomerUpdatePhoneFields(el);
          return;
        }
        el.style.setProperty('width',width,'important');
        el.style.setProperty('max-width',width,'important');
        el.style.setProperty('min-width',width,'important');
        el.style.setProperty('flex-basis',width,'important');
        const wrap=el.closest&&el.closest('.tm-mod-phone-readonly-wrap');
        if(wrap){
          wrap.style.setProperty('width',width,'important');
          wrap.style.setProperty('max-width',width,'important');
          wrap.style.setProperty('min-width',width,'important');
          wrap.style.setProperty('flex-basis',width,'important');
        }
        const slot=el.closest&&el.closest('.tm-phone-slot');
        if(slot)applyPhoneSlotWidth(slot,w);
        const cuRow=el.closest&&el.closest('.tm-cu-phone-host-v .tm-cu-phone-input-line');
        if(cuRow)cuRow.style.setProperty('grid-template-columns',width+' auto','important');
      }catch(_){}
    });
  }catch(_){}finally{
    try{setTimeout(function(){window.__tmPhoneShortWidthApplying=false;},0);}catch(__){window.__tmPhoneShortWidthApplying=false;}
  }
}
function applyPhoneSlotWidth(slot,w){
  try{
    const width=Math.max(72,Math.ceil(Number(w)||0))+'px';
    const row=slot.querySelector('.tm-phone-slot-row');
    const remove=row&&row.querySelector('#phoneRemoveBtn');
    const hasRemove=!!(remove&&getComputedStyle(remove).display!=='none');
    const hasCall=!!(row&&row.querySelector('.tm-mod-phone-call-btn'));
    const hasNoCall=!!(row&&row.querySelector('.tm-mod-phone-nocall-label'));
    const rowCols=[width];
    if(hasRemove)rowCols.push('28px');
    else if(hasCall)rowCols.push('20px');
    if(hasNoCall)rowCols.push('auto');
    const extra=hasRemove?33:(hasCall?25:0);
    const slotW=(Math.max(72,Math.ceil(Number(w)||0))+extra)+'px';
    if(!hasNoCall){
      slot.style.setProperty('width',slotW,'important');
      slot.style.setProperty('max-width',slotW,'important');
      slot.style.setProperty('flex-basis',slotW,'important');
    }
    if(row){
      row.style.setProperty('grid-template-columns',rowCols.join(' '),'important');
      row.style.setProperty('column-gap',rowCols.length>1?'5px':'0','important');
      if(!hasNoCall)row.style.setProperty('width',slotW,'important');
    }
  }catch(_){}
}
