function armPhoneShortWidthSettler(ms){
  try{
    const end=Date.now()+(Number(ms)||3500);
    if(window.__tmPhoneShortWidthSettler)clearInterval(window.__tmPhoneShortWidthSettler);
    schedulePhoneShortWidthSync();
    window.__tmPhoneShortWidthSettler=setInterval(function(){
      schedulePhoneShortWidthSync();
      if(Date.now()>end){
        clearInterval(window.__tmPhoneShortWidthSettler);
        window.__tmPhoneShortWidthSettler=0;
      }
    },140);
  }catch(_){}
}
function installPhoneShortWidthKeeper(){
  try{
    if(window.__tmPhoneShortWidthKeeperInstalled)return;
    window.__tmPhoneShortWidthKeeperInstalled=true;
    document.addEventListener('input',function(e){
      const t=e&&e.target;
      if(t&&t.matches&&t.matches('#phList .phone-short,.tm-cu-phone-host-v input,.tm-cu-phone-host-v textarea'))schedulePhoneShortWidthSync();
    },true);
    document.addEventListener('change',function(e){
      const t=e&&e.target;
      if(t&&t.matches&&t.matches('#phList .phone-short,.tm-cu-phone-host-v input,.tm-cu-phone-host-v textarea'))schedulePhoneShortWidthSync();
    },true);
    document.addEventListener('focusin',function(e){
      const t=e&&e.target;
      if(t&&t.matches&&t.matches('#phList .phone-short,.tm-cu-phone-host-v input,.tm-cu-phone-host-v textarea'))schedulePhoneShortWidthSync();
    },true);
    try{
      const obs=new MutationObserver(function(muts){
        if(window.__tmPhoneShortWidthApplying)return;
        for(let i=0;i<muts.length;i++){
          const n=muts[i]&&muts[i].target;
          if(n&&n.nodeType===1&&(
            (n.matches&&n.matches('#phList,#phList *,.tm-cu-phone-host-v,.tm-cu-phone-host-v *'))||
            (n.closest&&n.closest('#phList,.tm-cu-phone-host-v'))
          )){
            schedulePhoneShortWidthSync();
            return;
          }
        }
      });
      obs.observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['style','class','value']});
      window.__tmPhoneShortWidthKeeperObs=obs;
    }catch(_){}
    window.__tmPhoneShortWidthKeeperTimer=setInterval(schedulePhoneShortWidthSync,1200);
  }catch(_){}
}
