function fmtDateRu(iso){if(!iso)return'';const p=iso.split('-');if(p.length!==3)return'';return `${p[2]}.${p[1]}.${p[0]}`;}
function onDateChange(){const raw=document.getElementById('dvDate');const disp=document.getElementById('dvDateDisplay');const txtEl=document.getElementById('dvDateDisplayText');if(!disp||!txtEl)return;const txt=raw&&raw.value?fmtDateRu(raw.value):'';txtEl.textContent=txt||'дд.мм.гггг';disp.classList.toggle('has-value',!!txt);}
const RU_MONTHS=['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];
const RU_DOW=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
let dvCalState={year:0,month:0};
let dvCalNode=null;
let dvCalSingleCloserBound=false;
function pad2(n){return String(n).padStart(2,'0');}
function toIso(y,m,d){return `${y}-${pad2(m+1)}-${pad2(d)}`;}
function parseIsoDate(v){if(!v||!/^\d{4}-\d{2}-\d{2}$/.test(v))return null;const p=v.split('-').map(Number);return{y:p[0],m:p[1]-1,d:p[2]};}
function getCityToday(){
  const nowText=((document.getElementById('rNowD')&&document.getElementById('rNowD').textContent)||'').replace(/[()]/g,'').trim();
  const m=nowText.match(/^(\d{2})\.(\d{2})\.(\d{2})$/);
  if(m){
    const dd=Number(m[1]),mm=Number(m[2]),yy=Number(m[3]);
    const yyyy=2000+yy;
    return {y:yyyy,m:mm-1,d:dd};
  }
  const n=new Date();
  return {y:n.getFullYear(),m:n.getMonth(),d:n.getDate()};
}
function daysInMonth(y,m){return new Date(y,m+1,0).getDate();}
function firstDowMon(y,m){return (new Date(y,m,1).getDay()+6)%7;}
