function updatePinnedInfo(){
  try{
    var doc=getBridgeDoc();
    var infoPin=document.getElementById('infoPinned');
    if(!infoPin)return;
    var p=doc&&doc.querySelector('div#cityTimeTable > p.blockquote-small');
    var txt=p?(p.textContent||p.innerText||'').trim():'';
    var refresh=window.__tmPinnedCityRefresh;
    if(refresh){
      var elapsed=Date.now()-Number(refresh.at||0);
      var compact=txt.replace(/\s+/g,' ').trim();
      var oldText=String(refresh.oldText||'').replace(/\s+/g,' ').trim();
      if(elapsed>20000){
        window.__tmPinnedCityRefresh=null;
      }else if(!compact){
        window.__tmPinnedCityRefresh=null;
      }else if(oldText&&compact===oldText){
        txt='';
      }else{
        window.__tmPinnedCityRefresh=null;
      }
    }
    infoPin.classList.add('info-pinned');
    infoPin.innerHTML=formatPinnedInfoHtml(txt);
  }catch(e){}
}
function updateClosedRequestInfo(txt){
  try{
    var info=document.getElementById('infoClosedRequest');
    if(!info){
      var rowsRoot=document.querySelector('.info-rows');
      if(!rowsRoot)return;
      var row=document.createElement('div');
      row.className='info-row info-row--expand tm-info-panel-row tm-info-panel-row-closed';
      row.style.display='none';
      var key=document.createElement('span');
      key.className='info-k tm-info-panel-key';
      key.textContent='Заявка закрыта:';
      info=document.createElement('span');
      info.className='info-v tm-info-panel-value info-closed-request';
      info.id='infoClosedRequest';
      info.textContent='—';
      row.appendChild(key);
      row.appendChild(info);
      rowsRoot.appendChild(row);
    }
    if(!txt&&typeof __tmExtractClosedRequestInfo==='function'){
      try{txt=window.__tmNativeClosedRequestInfo||__tmExtractClosedRequestInfo(window.__tmNativeRequestForm)||__tmExtractClosedRequestInfo(document)||'';}catch(_){}
    }
    txt=String(txt||'').replace(/\s+/g,' ').trim();
    txt=txt.replace(/^Заявка\s+закрыта\s*/i,'').trim();
    info.textContent=txt||'—';
    var row=info.closest('.info-row');
    if(row)row.style.display=txt?'block':'none';
    decorateInfoRows();
  }catch(e){}
}
function syncInfoBlock(){
  decorateInfoRows();
  updatePinnedInfo();
  var infoPartner=document.getElementById('infoPartner');
  if(!infoPartner)return;
  var prev=String(infoPartner.textContent||'').trim();
  try{
    var doc=getBridgeDoc();
    var pcb=doc&&doc.getElementById('partnerCommentBlock');
    var txt=pcb?(pcb.textContent||pcb.innerText||'').trim():'';
    txt=txt.replace(/^Комментарий\s+о\s+партнере[:\s]*/i,'').trim();
    if(txt){infoPartner.innerHTML=formatPartnerInfoHtml(txt);return;}
    // Пока bridge не готов, не стираем уже подставленный комментарий из init.
    if(!doc)return;
  }catch(e){
    if(prev&&prev!=='—')return;
  }
  if(!prev||prev==='—')infoPartner.innerHTML='<span class="partner-empty">—</span>';
}
function rememberPendingBridgeFlag(fieldId,isOn){
  window.__tmPendingBridgeFlags=window.__tmPendingBridgeFlags||{};
  window.__tmPendingBridgeFlags[String(fieldId||'')]=!!isOn;
}
function flushPendingBridgeFlags(doc){
  var pend=window.__tmPendingBridgeFlags||{};
  var keys=Object.keys(pend);
  if(!keys.length)return;
  var d=doc||getBridgeDoc();
  if(!d)return;
  keys.forEach(function(fieldId){
    var cb=d.getElementById(fieldId);
    if(!cb)return;
    var isOn=!!pend[fieldId];
    if(cb.checked!==isOn){
      cb.checked=isOn;
      try{cb.dispatchEvent(new Event('change',{bubbles:true}));}catch(_e1){}
      try{cb.dispatchEvent(new Event('input',{bubbles:true}));}catch(_e2){}
    }
    delete pend[fieldId];
  });
}
function syncFlagToBridge(fieldId,isOn){
  try{
    rememberPendingBridgeFlag(fieldId,isOn);
    var doc=getBridgeDoc();
    if(!doc)return false;
    var cb=doc.getElementById(fieldId);
    if(!cb)return false;
    if(cb.checked!==!!isOn){
      cb.checked=!!isOn;
      cb.dispatchEvent(new Event('change',{bubbles:true}));
      cb.dispatchEvent(new Event('input',{bubbles:true}));
    }
    var pend=window.__tmPendingBridgeFlags||{};
    delete pend[String(fieldId||'')];
    return true;
  }catch(e){return false;}
}
function syncFlagsFromBridge(){
  try{
    var doc=getBridgeDoc();
    if(!doc){syncInfoBlock();return;}
    installBridgeDerivedUiObserver(doc);
    flushPendingBridgeFlags(doc);
    var flagMap={'flagPinned':'customerrequest-is_zakrep','flagUrgent':'customerrequest-is_urgent','flagReview':'customerrequest-is_req_fback','flagCallCheck':'customerrequest-is_need_call_check','flagCallBefore':'customerrequest-is_need_call_before_visit'};
    Object.keys(flagMap).forEach(function(uiId){
      var cb=doc.getElementById(flagMap[uiId]);if(!cb)return;
      var pill=document.getElementById(uiId);if(pill)pill.classList.toggle('on',!!cb.checked);
    });
    syncInfoBlock();
  }catch(e){}
}
function installBridgeDerivedUiObserver(doc){
  try{
    if(!doc||doc.__tmBridgeDerivedUiObserverBound)return;
    doc.__tmBridgeDerivedUiObserverBound=true;
    var raf=0;
    function schedule(){
      if(raf)return;
      raf=requestAnimationFrame(function(){
        raf=0;
        try{
          var meta=readBridgeTimeMeta(doc);
          if(meta&&(isValidHm(meta.cityTime)||isValidHm(meta.reqTime)))tmApplyBridgeTimeMetaLive(meta,{force:false});
        }catch(_e_time){}
        try{syncFlagsFromBridge();}catch(_e_flags){}
      });
    }
    var targets=[
      doc.querySelector('.field-customerrequest-opened_at'),
      doc.querySelector('#display-exact-time'),
      detectBridgeTimeField(doc),
      detectBridgeDateField(doc),
      doc.querySelector('#cityTimeTable'),
      doc.querySelector('div#cityTimeTable > p.blockquote-small'),
      doc.getElementById('customerrequest-is_zakrep'),
      doc.getElementById('customerrequest-is_urgent'),
      doc.getElementById('customerrequest-is_req_fback'),
      doc.getElementById('customerrequest-is_need_call_check'),
      doc.getElementById('customerrequest-is_need_call_before_visit')
    ].filter(Boolean);
    if(!targets.length)return;
    var mo=new MutationObserver(schedule);
    targets.forEach(function(t){
      try{mo.observe(t,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['checked','value','class','style']});}catch(_e_obs){}
      try{t.addEventListener('input',schedule,true);}catch(_e_in){}
      try{t.addEventListener('change',schedule,true);}catch(_e_ch){}
    });
    doc.__tmBridgeDerivedUiObserver=mo;
  }catch(_){}
}
function togglePill(el){
  el.classList.toggle('on');
  var on=el.classList.contains('on');
  syncInfoBlock();
  var idMap={'flagPinned':'customerrequest-is_zakrep','flagUrgent':'customerrequest-is_urgent','flagReview':'customerrequest-is_req_fback','flagCallCheck':'customerrequest-is_need_call_check','flagCallBefore':'customerrequest-is_need_call_before_visit'};
  var bridgeId=idMap[el.id];
  if(bridgeId)syncFlagToBridge(bridgeId,on);
  if(el.id==='flagCallBefore'&&!on){
    var ta=getUiMainCommentField();
    if(ta){
      ta.value=ta.value.replace(/Позвонить перед выездом[\.\,\s]*/gi,'').trim();
      ta.dispatchEvent(new Event('input',{bubbles:true}));
      syncSourceComment(ta.value);
    }
  }
}
