function syncTimeGridFromInputs(){
  const tEl=document.getElementById('dvTime');
  const hEl=document.getElementById('dvHour');
  const inp=document.getElementById('dvQuickTimeInput');
  if(tmShouldClearUiRequestTime()){
    tmClearUiRequestTimeControls();
    updateRequestTimeBadge();
    return;
  }
  const allowHourFallback=!isBridgeRequestTimeEmptyUi()||!!window.__tmTimeExplicitlySet||!!Number(window.__tmActiveTimeOffsetHours||0);
  const time=((tEl?tEl.value:'')||(allowHourFallback&&hEl?hEl.value:'')||'').trim();
  if(inp)inp.value=time||'';
  syncTimeOffsetButtonsUi();
  updateRequestTimeBadge();
}
