function autoConfirmTimeReasonModalForCityChangeInDoc(doc){
  try{
    if(!doc||!isCityChangeTimeReasonAutoConfirmArmed())return false;
    var state=window.__tmCityTimeReasonAutoConfirm;
    var modal=doc.getElementById('timeChangeReasonModal');
    if(!modal)return false;
    var win=doc.defaultView||window;
    var cs=win.getComputedStyle?win.getComputedStyle(modal):null;
    var visible=modal.classList.contains('show')||((cs&&cs.display)||'')!=='none';
    if(!visible)return false;
    var submitBtn=modal.querySelector('.modal-footer button.btn.btn-primary, .modal-footer .btn.btn-primary, button[type="submit"], input[type="submit"]');
    if(!submitBtn)return false;
    if(submitBtn.disabled||String(submitBtn.getAttribute('aria-disabled')||'').toLowerCase()==='true')return false;
    var txt=String(modal.textContent||'').replace(/\s+/g,' ').trim();
    var hasClient=/клиент/i.test(txt);
    var hasChoose=/выбрат/i.test(String(submitBtn.textContent||submitBtn.value||''));
    var hasReasonField=!!(modal.querySelector('#timeChangeReasonModalSelect')||modal.querySelector('select')||modal.querySelector('#customerrequest-cr_form_extra-timechangereason')||modal.querySelector('input[name="CustomerRequest[cr_form_extra][timeChangeReason]"]'));
    if(!hasChoose||!hasReasonField)return false;
    if(!hasClient&&Date.now()-Number(state.armedAt||0)<900)return false;
    if(Date.now()-Number(state.lastSubmitAt||0)<900)return false;
    state.lastSubmitAt=Date.now();
    suppressBeforeUnload(8000);
    if(!tmSingleProgrammaticClick(submitBtn,900))return false;
    setTimeout(function(){try{forceCloseTimeReasonModalInDoc(doc);}catch(_){}},500);
    setTimeout(function(){try{forceCloseTimeReasonModalInDoc(doc);}catch(_){}},1200);
    clearCityChangeTimeReasonAutoConfirm();
    return true;
  }catch(_){return false;}
}
function scheduleCityChangeTimeReasonAutoConfirm(){
  if(!isCityChangeTimeReasonAutoConfirmArmed())return;
  var delays=[0,50,120,220,360,560,860,1200,1700,2400,3200,4200,5600,7200];
  for(var i=0;i<delays.length;i++){
    (function(ms){
      setTimeout(function(){
        try{
          if(!isCityChangeTimeReasonAutoConfirmArmed())return;
          var hit=false;
          try{hit=autoConfirmTimeReasonModalForCityChangeInDoc(document)||hit;}catch(_){}
          try{hit=autoConfirmTimeReasonModalForCityChangeInDoc(getBridgeDoc())||hit;}catch(_){}
          if(hit)clearCityChangeTimeReasonAutoConfirm();
        }catch(_){}
      },ms);
    })(delays[i]);
  }
}
function isActiveTimeReasonWorkStatusNow(){
  try{
    if(document.body&&document.body.classList&&document.body.classList.contains('tm-closed-readonly-mode'))return false;
    if(document.body&&document.body.classList&&document.body.classList.contains('tm-active-work-mode'))return true;
    var parts=[];
    var badge=document.querySelector('.crm-status-badge');
    if(badge)parts.push(badge.textContent||'',badge.className||'');
    var title=document.querySelector('.t-title');
    if(title)parts.push(title.textContent||'');
    var info=document.querySelector('#reqInfo');
    if(info)parts.push(info.textContent||'');
    var probe=parts.join(' ').toLowerCase().replace(/\s+/g,' ').trim();
    if(!probe)return false;
    if(probe.indexOf('модерац')!==-1||probe.indexOf('уточнен')!==-1)return false;
    return /(^|\s)(ожидает|в пути|в работе|в работе сд)(\s|$)/.test(probe)
      || /crm-status-(ozhidaet|v-puti|v-rabote|v-rabote-sd)/.test(probe);
  }catch(_){return false;}
}
