function isValidHm(v){return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(v||'').trim());}
function tmShortDateForLateComment(v){
  var m=String(v||'').replace(/[()]/g,'').trim().match(/(\d{2})\.(\d{2})(?:\.(\d{2,4}))?/);
  return m?m[1]+'.'+m[2]:'';
}
function tmPluralRu(n,one,two,five){
  n=Math.abs(Number(n)||0);
  var n10=n%10,n100=n%100;
  if(n10===1&&n100!==11)return one;
  if(n10>=2&&n10<=4&&(n100<12||n100>14))return two;
  return five;
}
function tmLateDurationForComment(mins){
  mins=Math.max(0,Math.abs(Number(mins)||0));
  var days=Math.floor(mins/1440);
  mins-=days*1440;
  var hrs=Math.floor(mins/60);
  var mm=mins-hrs*60;
  var parts=[];
  if(days)parts.push(days+' '+tmPluralRu(days,'день','дня','дней'));
  if(hrs)parts.push(hrs+' '+tmPluralRu(hrs,'час','часа','часов'));
  if(mm||!parts.length)parts.push(mm+' '+tmPluralRu(mm,'минута','минуты','минут'));
  return parts.join(' ');
}
function tmAppendUniqueServiceCommentLine(base,line){
  base=String(base||'').replace(/\r/g,'');
  line=String(line||'').trim();
  if(!line)return base;
  var needle=line.replace(/\s+/g,' ').toLowerCase();
  var rows=base?base.split('\n'):[];
  for(var i=0;i<rows.length;i++){
    if(String(rows[i]||'').replace(/\s+/g,' ').trim().toLowerCase()===needle)return base;
  }
  return base?(base.replace(/\s+$/,'')+'\n'+line):line;
}
function tmApplyLateArrivalToServiceComment(line,badge){
  line=String(line||'').trim();
  if(!line)return;
  var ta=getUiServiceCommentField();
  var bridgeVal='';
  try{bridgeVal=pickBestBridgeServiceCommentValue()||'';}catch(_){}
  var src=((ta&&ta.value)||bridgeVal||'');
  var next=tmAppendUniqueServiceCommentLine(src,line);
  if(ta){
    ta.value=next;
    try{cc(ta,'n2');}catch(_){}
    try{ta.dispatchEvent(new Event('input',{bubbles:true}));}catch(_){}
    try{ta.dispatchEvent(new Event('change',{bubbles:true}));}catch(_){}
    try{ta.dispatchEvent(new Event('blur',{bubbles:true}));}catch(_){}
  }
  try{
    getBridgeServiceCommentTargets().forEach(function(t){
      if(!t)return;
      t.value=next;
      t.dispatchEvent(new Event('input',{bubbles:true}));
      t.dispatchEvent(new Event('change',{bubbles:true}));
      t.dispatchEvent(new Event('blur',{bubbles:true}));
    });
  }catch(_){}
  syncSourceServiceComment(next,0,{forceNotify:true,forceBlur:true});
  setTimeout(function(){syncSourceServiceComment(next,0,{forceNotify:true,forceBlur:true});},30);
  if(badge){
    try{
      badge.classList.remove('tm-late-comment-added');
      void badge.offsetWidth;
      badge.classList.add('tm-late-comment-added');
      clearTimeout(badge.__tmLateCommentAddedTimer);
      badge.__tmLateCommentAddedTimer=setTimeout(function(){try{badge.classList.remove('tm-late-comment-added');}catch(_){}},520);
    }catch(_){}
  }
}
function tmEnsureLateBadgeClickHandler(){
  if(document.__tmLateBadgeClickBound)return;
  document.__tmLateBadgeClickBound=true;
  function activateLateBadge(e){
    var target=e&&e.target;
    var badge=target&&target.closest?target.closest('#tmRequestTimeDeltaBadge'):null;
    if(!badge)return;
    if(e.type==='pointerdown'&&typeof e.button==='number'&&e.button!==0)return;
    if(e.type==='click'&&Date.now()-Number(badge.__tmLateActivatedAt||0)<700){
      e.preventDefault();
      e.stopPropagation();
      if(typeof e.stopImmediatePropagation==='function')e.stopImmediatePropagation();
      return;
    }
    try{updateRequestTimeBadge();}catch(_){}
    badge=document.getElementById('tmRequestTimeDeltaBadge');
    var line=String(badge&&badge.getAttribute('data-tm-late-service-comment')||'').trim();
    if(!line)return;
    if(e){
      e.preventDefault();
      e.stopPropagation();
      if(typeof e.stopImmediatePropagation==='function')e.stopImmediatePropagation();
    }
    badge.__tmLateActivatedAt=Date.now();
    tmApplyLateArrivalToServiceComment(line,badge);
  }
  window.addEventListener('pointerdown',activateLateBadge,true);
  window.addEventListener('click',activateLateBadge,true);
}
function updateRequestTimeBadge(){
  try{
    tmEnsureLateBadgeClickHandler();
    var badge=document.getElementById('tmRequestTimeDeltaBadge');
    if(!badge)return;
    function readStableRequestStatus(){
      var parts=[];
      try{parts.push(window.__tmCurrentModeLabelForTimeBadge||'');}catch(_){}
      try{
        var top=document.querySelector('.t-title .crm-status-badge[data-tm-native-status="1"],.t-title .tm-status-badge');
        if(top){
          parts.push(top.getAttribute('data-tm-status-label')||'');
          parts.push(top.className||'');
          var visible=String((top.querySelector('.tm-status-text,.badge-text')||top).textContent||'').trim();
          if(visible&&visible.toLowerCase()!=='готово!')parts.push(visible);
        }
      }catch(_){}
      try{
        var native=document.querySelector('form#customerRequestForm .card-header .crm-status-badge,#reqInfo .crm-status-badge');
        if(native){
          parts.push(native.className||'');
          var nText=String(native.textContent||'').trim();
          if(nText&&nText.toLowerCase()!=='готово!')parts.push(nText);
        }
      }catch(_){}
      try{parts.push((document.querySelector('.t-title')||{}).textContent||'');}catch(_){}
      return parts.join(' ').toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
    }
    var statusTxt=readStableRequestStatus();
    if(!(statusTxt.indexOf('ожидает')!==-1||statusTxt.indexOf('в пути')!==-1||statusTxt.indexOf('crm-status-ozhidaet')!==-1||statusTxt.indexOf('tm-status-ozhidaet')!==-1||statusTxt.indexOf('crm-status-v-puti')!==-1||statusTxt.indexOf('tm-status-v-puti')!==-1)){
      badge.style.display='none';
      badge.removeAttribute('data-tm-late-service-comment');
      return;
    }
    var cityT=String((document.getElementById('rNowT')||{}).textContent||'').trim();
    var cityD=String((document.getElementById('rNowD')||{}).textContent||'').replace(/[()]/g,'').trim();
    var reqT=String((document.getElementById('rReqT')||{}).textContent||'').trim();
    var reqD=String((document.getElementById('rReqD')||{}).textContent||'').replace(/[()]/g,'').trim();
    var inputT=String(((document.getElementById('dvQuickTimeInput')||{}).value)||((document.getElementById('dvTime')||{}).value)||'').trim();
    if((!isValidHm(reqT)||reqT==='--:--')&&isValidHm(inputT))reqT=inputT;
    if(!isValidHm(cityT)||!isValidHm(reqT)||reqT==='--:--'){
      badge.style.display='none';
      badge.removeAttribute('data-tm-late-service-comment');
      return;
    }
    function parseDt(dateTxt,timeTxt,fallbackDateTxt){
      var d=String(dateTxt||fallbackDateTxt||'').replace(/[()]/g,'').trim();
      var tm=String(timeTxt||'').trim();
      if(!isValidHm(tm))return null;
      var dm=d.match(/(\d{2})\.(\d{2})\.(\d{2,4})/);
      var now=new Date();
      var day=now.getDate(),mon=now.getMonth()+1,yr=now.getFullYear();
      if(dm){
        day=parseInt(dm[1],10);
        mon=parseInt(dm[2],10);
        yr=parseInt(dm[3],10);
        if(yr<100)yr+=2000;
      }
      var tp=tm.split(':');
      return new Date(yr,mon-1,day,parseInt(tp[0],10),parseInt(tp[1],10),0,0);
    }
    var cityDt=parseDt(cityD,cityT,'');
    var reqDt=parseDt(reqD,reqT,cityD);
    if(!cityDt||!reqDt){
      badge.style.display='none';
      badge.removeAttribute('data-tm-late-service-comment');
      return;
    }
    var diff=Math.round((reqDt.getTime()-cityDt.getTime())/60000);
    function fmt(mins){
      mins=Math.max(0,Math.abs(Number(mins)||0));
      var days=Math.floor(mins/1440);
      mins-=days*1440;
      var hrs=Math.floor(mins/60);
      var mm=mins-hrs*60;
      var parts=[];
      if(days)parts.push(days+' д');
      if(hrs)parts.push(hrs+' ч');
      if(mm||!parts.length)parts.push(mm+' мин');
      return parts.slice(0,2).join(' ');
    }
    var late=diff<0;
    var lateMinutes=Math.abs(diff);
    var lateClickable=late&&lateMinutes>=11;
    var soon=!late&&diff<=30;
    var prefix=late?'Опоздание':(diff===0?'Время':'Осталось');
    var value=diff===0?'сейчас':fmt(diff);
    var icon=late?'ti-alert-circle':(soon?'ti-clock-exclamation':'ti-clock-hour-4');
    badge.style.display='inline-flex';
    badge.className='tm-time-left-badge '+(late?'is-late':(soon?'is-soon':'is-ok'))+(lateClickable?' is-clickable':'');
    function escTxt(s){return String(s||'').replace(/[&<>"]/g,function(ch){return ch==='&'?'&amp;':ch==='<'?'&lt;':ch==='>'?'&gt;':'&quot;';});}
    badge.innerHTML='<i class="ti '+icon+'"></i><span class="tm-time-left-prefix">'+escTxt(prefix)+'</span><span class="tm-time-left-value">'+escTxt(value)+'</span>';
    if(lateClickable){
      var reqShort=tmShortDateForLateComment(reqD||cityD);
      var cityShort=tmShortDateForLateComment(cityD||reqD);
      badge.setAttribute('data-tm-late-service-comment','Заявка была на '+reqShort+' '+reqT+' мастера еще не было а время в городе '+cityShort+' '+cityT+' - опоздание '+tmLateDurationForComment(lateMinutes));
      badge.title='Добавить опоздание в служебный комментарий';
    }else{
      badge.removeAttribute('data-tm-late-service-comment');
      badge.removeAttribute('title');
    }
    var base='display:inline-flex;align-items:center;gap:5px;height:24px;margin-left:auto;padding:0 9px 0 8px;border-radius:999px;font-size:11.5px;font-weight:500;line-height:1;white-space:nowrap;box-shadow:0 1px 2px rgba(45,41,32,.04),inset 0 1px 0 rgba(255,255,255,.75);';
    var ico='.tm-time-left-badge i{font-size:13px;line-height:1;flex:0 0 auto;opacity:.9}.tm-time-left-badge span{position:relative;top:-.15px}.tm-time-left-badge .tm-time-left-prefix{font-weight:500;opacity:.82}.tm-time-left-badge .tm-time-left-value{font-weight:650;letter-spacing:-.01em}.tm-time-left-badge.is-clickable{cursor:pointer;transition:transform .16s ease,box-shadow .16s ease,filter .16s ease}.tm-time-left-badge.is-clickable:hover{transform:translateY(-1px);filter:saturate(1.04)}.tm-time-left-badge.tm-late-comment-added{transform:scale(.965);box-shadow:0 0 0 3px rgba(216,51,64,.10),0 3px 10px rgba(216,51,64,.12),inset 0 1px 0 rgba(255,255,255,.8) !important}';
    if(!document.getElementById('tm-time-left-badge-style')){
      var st=document.createElement('style');
      st.id='tm-time-left-badge-style';
      st.textContent=ico;
      document.head.appendChild(st);
    }
    if(late){
      badge.style.cssText=base+'border:.5px solid rgba(199,31,48,.22);background:linear-gradient(180deg,#FFF7F7 0%,#FFECEC 100%);color:#B81928;';
    }else if(soon){
      badge.style.cssText=base+'border:.5px solid rgba(210,116,46,.25);background:linear-gradient(180deg,#FFF9EA 0%,#FFF0CF 100%);color:#89530B;';
    }else{
      badge.style.cssText=base+'border:.5px solid rgba(70,181,89,.22);background:linear-gradient(180deg,#F4FCF6 0%,#EAF8EE 100%);color:#176C31;';
    }
    badge.style.cursor=lateClickable?'pointer':'';
  }catch(_){}
}
function readBridgeExactRequestMeta(doc){
  try{
    if(!doc)return {time:'',date:''};
    var exactNodes=[
      doc.querySelector('#display-exact-time span'),
      doc.querySelector('#display-exact-time'),
      doc.querySelector('#crOpenedTime')
    ].filter(Boolean);
    for(var ei=0;ei<exactNodes.length;ei++){
      var node=exactNodes[ei];
      var raw=('value' in node)?node.value:(node.textContent||node.getAttribute&&node.getAttribute('value')||'');
      var em=String(raw||'').match(/([0-2]\d:[0-5]\d)(?:\s*\((\d{2}\.\d{2}\.\d{2,4})\))?/);
      if(em&&isValidHm(em[1])&&em[1]!=='00:00')return {time:em[1],date:em[2]||''};
    }
  }catch(_){}
  return {time:'',date:''};
}
function readBridgeExactRequestTime(doc){
  var meta=readBridgeExactRequestMeta(doc);
  return meta&&meta.time||'';
}
function readBridgeDisplayCityMeta(doc){
  try{
    if(!doc)return {time:'',date:''};
    var nodes=[
      doc.querySelector('#display-city-time span'),
      doc.querySelector('#display-city-time'),
      doc.querySelector('#cityTime')
    ].filter(Boolean);
    for(var i=0;i<nodes.length;i++){
      var raw=String(nodes[i].textContent||nodes[i].value||'').trim();
      var m=raw.match(/([0-2]?\d:[0-5]\d)(?:\s*\((\d{2}\.\d{2}\.\d{2,4})\))?/);
      if(m&&isValidHm(m[1]))return {time:m[1].length===4?('0'+m[1]):m[1],date:m[2]||''};
    }
  }catch(_){}
  return {time:'',date:''};
}
function readBridgeTimeMeta(doc){
  var out={cityTime:'',cityDate:'',reqTime:'',reqDate:'',reqTimeSource:''};
  try{
    var label=doc&&doc.querySelector('.field-customerrequest-opened_at label');
    var txt=String(label&&label.textContent||'').replace(/\s+/g,' ').trim();
    var m=txt.match(/Время\s*города:\s*([0-2]\d:[0-5]\d)\s*\((\d{2}\.\d{2}\.\d{2})\)/i);
    if(m){out.cityTime=m[1];out.cityDate=m[2];}
    m=txt.match(/Время\s*заявки:\s*([0-2]\d:[0-5]\d|--:--)\s*(?:\((\d{2}\.\d{2}\.\d{2})\))?/i);
    if(m){out.reqTime=m[1];out.reqTimeSource='label';if(m[2])out.reqDate=m[2];}
    if(!isValidHm(out.cityTime)||!out.cityDate){
      var cityMeta=readBridgeDisplayCityMeta(doc);
      if(!isValidHm(out.cityTime)&&isValidHm(cityMeta.time))out.cityTime=cityMeta.time;
      if(!out.cityDate&&cityMeta.date)out.cityDate=cityMeta.date;
    }
    var exactMeta=readBridgeExactRequestMeta(doc);
    var exactTime=exactMeta&&exactMeta.time||'';
    var allowCityRefreshExact=!!window.__tmCityTimeRefreshToken&&isValidHm(out.cityTime);
    var canUseExactTime=isValidHm(out.cityTime)&&(out.reqTime!=='--:--'||allowCityRefreshExact);
    if(canUseExactTime&&isValidHm(exactTime)&&exactTime!=='00:00'&&out.reqTime!==exactTime){
      out.reqTime=exactTime;
      out.reqTimeSource='exact';
      if(exactMeta&&exactMeta.date)out.reqDate=exactMeta.date;
    }else if(canUseExactTime&&((!isValidHm(out.reqTime))||out.reqTime==='--:--')&&isValidHm(exactTime)&&exactTime!=='00:00'){
      out.reqTime=exactTime;
      out.reqTimeSource='exact';
      if(exactMeta&&exactMeta.date)out.reqDate=exactMeta.date;
    }else if(isValidHm(out.reqTime)&&exactMeta&&exactMeta.date){
      out.reqDate=exactMeta.date;
    }
  }catch(e){}
  return out;
}
function applyBridgeTimeMeta(meta){
  if(!meta)return;
  try{meta=tmNormalizeRequestDateAfterCity(meta);}catch(_norm){}
  var nowT=document.getElementById('rNowT');var nowD=document.getElementById('rNowD');
  var reqT=document.getElementById('rReqT');var reqD=document.getElementById('rReqD');
  // Bridge — авторитетный источник: показываем время напрямую, не ждём isCitySelectedUi()
  if(nowT&&isValidHm(meta.cityTime))nowT.textContent=meta.cityTime;
  if(nowD&&meta.cityDate)nowD.textContent='('+meta.cityDate+')';
  if(reqT){
    if(meta.reqTime==='--:--'){
      reqT.textContent='--:--';
      if(tmShouldClearUiRequestTime(meta)){
        tmClearUiRequestTimeControls();
        try{updDv();}catch(_clearDv){}
      }
    }else if(isValidHm(meta.reqTime)&&(meta.reqTimeSource==='label'||window.__tmTimeExplicitlySet||meta.reqTime!==meta.cityTime)){
      reqT.textContent=meta.reqTime;
    }
  }
  if(reqD&&meta.reqDate)reqD.textContent='('+meta.reqDate+')';
  updateRequestTimeBadge();
}
