function detectSelectedTimeFromTable(doc){
  try{
    if(!doc)return '';
    var td=doc.querySelector('#cityTimeTable td.timecode-selected')||doc.querySelector('#cityTimeTable td[data-key].timecode-is-cot');
    if(!td)return '';
    var key=String(td.getAttribute('data-key')||'').trim();
    if(/^\d{2}:\d{2}$/.test(key))return key;
    var m=String(td.textContent||'').match(/([0-2]\d:[0-5]\d)/);
    return m?m[1]:'';
  }catch(_e){return '';}
}
function getTimeCandidateDocs(){
  var out=[];
  function add(d){if(d&&out.indexOf(d)===-1)out.push(d);}
  try{add(getBridgeDoc());}catch(_){}
  try{add(window.__regionBridgeFrame&&window.__regionBridgeFrame.contentDocument);}catch(_){}
  try{add(document);}catch(_){}
  return out;
}
function syncDateToBridgeFromUi(){
  try{
    var doc=getBridgeDoc()||document;if(!doc)return;
    var ui=document.getElementById('dvDate');if(!ui)return;
    var src=detectBridgeDateField(doc);if(!src)return;
    var iso=(ui.value||'').trim();
    var next='';
    if(iso){
      if(src.type==='date'){
        next=iso;
      }else{
        var dm=iso.match(/^(\d{4})-(\d{2})-(\d{2})$/);
        next=dm?(dm[3]+'-'+dm[2]+'-'+dm[1]):'';
      }
    }
    var changed=String(src.value||'')!==next;
    if(changed)src.value=next;
    if(changed){
      src.dispatchEvent(new Event('input',{bubbles:true}));
      src.dispatchEvent(new Event('change',{bubbles:true}));
      var bw=doc.defaultView||doc.parentWindow;
      if(bw&&bw.jQuery){
        try{bw.jQuery(src).datepicker('update');}catch(e){}
        try{bw.jQuery(src).kvDatepicker('update');}catch(e){}
      }
    }
  }catch(e){}
}
function syncTimeToBridgeFromUi(opts){
  opts=opts||{};
  try{
    var doc=getBridgeDoc()||document;if(!doc)return;
    var src=detectBridgeTimeField(doc);
    var ui=(document.getElementById('dvTime')||{}).value||'';
    var next=String(ui||'').trim();
    // Критично: не затираем bridge пустым временем.
    if(!next)return;
    if(src){
      var changed=false;
      if(src.tagName==='SELECT'){
        var opt=Array.from(src.options||[]).find(function(o){return String(o.value||'').trim()===next||String(o.text||'').trim()===next;});
        if(opt&&String(src.value||'')!==String(opt.value||'')){src.value=opt.value;changed=true;}
      }else{
        if(String(src.value||'')!==next){src.value=next;changed=true;}
      }
      if(changed||opts.forceNotify){
        src.dispatchEvent(new Event('input',{bubbles:true}));
        src.dispatchEvent(new Event('change',{bubbles:true}));
      }
    }
    setRequestTimeSubmitMirrors(next);
    if(!opts.skipTimeCell){
      selectBridgeTimeCell(next);
    }
  }catch(e){}
  scheduleHideTimeChangeReasonModal();
}
function getTzOffsetFromMeta(meta){
  if(!meta||!isValidHm(meta.cityTime))return null;
  var p=meta.cityTime.split(':');
  var cityMin=parseInt(p[0],10)*60+parseInt(p[1],10);
  var now=new Date();
  var localMin=now.getHours()*60+now.getMinutes();
  var diff=cityMin-localMin;
  while(diff>720)diff-=1440;
  while(diff<-720)diff+=1440;
  return diff;
}
function tmReadBestTimeMeta(preferDoc){
  var out={cityTime:'',cityDate:'',reqTime:'',reqDate:'',reqTimeSource:''};
  try{
    var docs=[];
    function add(d){try{if(d&&docs.indexOf(d)===-1)docs.push(d);}catch(_){}}
    add(preferDoc);
    try{getTimeCandidateDocs().forEach(add);}catch(_){}
    add(document);
    for(var i=0;i<docs.length;i++){
      var m=readBridgeTimeMeta(docs[i])||{};
      if(!isValidHm(out.cityTime)&&isValidHm(m.cityTime))out.cityTime=m.cityTime;
      if(!out.cityDate&&m.cityDate)out.cityDate=m.cityDate;
      if((!isValidHm(out.reqTime)||out.reqTime==='--:--')&&m.reqTime)out.reqTime=m.reqTime;
      if(!out.reqDate&&m.reqDate)out.reqDate=m.reqDate;
      if(!out.reqTimeSource&&m.reqTimeSource)out.reqTimeSource=m.reqTimeSource;
      if(isValidHm(out.cityTime)&&out.cityDate&&out.reqTime)break;
    }
  }catch(_){}
  return out;
}
function tmRememberHourOffsetChoice(hours){
  try{
    hours=Number(hours)||0;
    if(hours!==1&&hours!==2)return;
    window.__tmLastHourOffsetChoice={hours:hours,at:Date.now()};
  }catch(_){}
}
function tmClearHourOffsetChoice(){
  try{window.__tmLastHourOffsetChoice=null;}catch(_){}
}
function tmGetActiveHourOffsetForCityReplay(){
  try{
    var active=Number(window.__tmActiveTimeOffsetHours||0);
    var hold=window.__tmTimeOffsetVisualHold;
    if((active!==1&&active!==2)&&hold&&Date.now()<Number(hold.until||0)){
      active=Number(hold.hours||0);
    }
    if(active===1||active===2)return active;
    var b1=document.getElementById('uiAddHour1');
    var b2=document.getElementById('uiAddHour2');
    if(b1&&b1.classList&&b1.classList.contains('on'))return 1;
    if(b2&&b2.classList&&b2.classList.contains('on'))return 2;
    var last=window.__tmLastHourOffsetChoice;
    if(last&&Date.now()-Number(last.at||0)<10*60*1000){
      var h=Number(last.hours||0);
      if(h===1||h===2)return h;
    }
  }catch(_){}
  return 0;
}
function tmReplayHourOffsetAfterSameTzCityChange(cityId,previousMeta,hours){
  try{
    hours=Number(hours)||0;
    if(hours!==1&&hours!==2)return;
    var targetCity=String(cityId||'').trim();
    if(!targetCity)return;
    var oldMeta=previousMeta||{};
    if(!isValidHm(oldMeta.cityTime))oldMeta=tmReadBestTimeMeta(document);
    var oldVisible=String((document.getElementById('rNowT')||{}).textContent||'').trim();
    if(isValidHm(oldVisible))oldMeta.cityTime=oldVisible;
    if(!isValidHm(oldMeta.cityTime))return;
    var oldTime=String(oldMeta.cityTime||'').trim();
    var oldHour=parseInt(String(oldMeta.cityTime).split(':')[0],10);
    var token=String(Date.now())+'-'+Math.random();
    window.__tmSameTzHourReplayToken=token;
    var started=Date.now();
    var done=false;
    var observer=null;
    function cleanup(){
      done=true;
      try{if(observer)observer.disconnect();}catch(_){}
    }
    function readCityTime(){
      var ui=String((document.getElementById('rNowT')||{}).textContent||'').trim();
      if(isValidHm(ui))return ui;
      var doc=getBridgeDoc()||document;
      var meta=readBridgeTimeMeta(doc)||{};
      if(isValidHm(meta.cityTime))return String(meta.cityTime||'').trim();
      meta=tmReadBestTimeMeta(doc)||{};
      return isValidHm(meta.cityTime)?String(meta.cityTime||'').trim():'';
    }
    function clearOffset(){
      window.__tmActiveTimeOffsetHours=0;
      window.__tmTimeOffsetVisualHold=null;
      syncTimeOffsetButtonsUi();
    }
    function replay(){
      window.__tmTimeExplicitlySet=true;
      window.__tmActiveTimeOffsetHours=hours;
      window.__tmTimeOffsetVisualHold={hours:hours,until:Date.now()+2200};
      window.__tmHourSyncLockUntil=0;
      syncTimeOffsetButtonsUi();
      if(clickBridgeHourButton(hours)){
        setTimeout(syncDateTimeFromBridge,80);
        setTimeout(syncDateTimeFromBridge,220);
        setTimeout(syncDateTimeFromBridge,520);
      }
    }
    function attempt(){
      if(done||window.__tmSameTzHourReplayToken!==token)return;
      var doc=getBridgeDoc()||document;
      var cityEl=doc&&(doc.getElementById('customerrequest-city_id')||doc.querySelector('select[name="CustomerRequest[city_id]"],input[name="CustomerRequest[city_id]"]'));
      var cityTime=readCityTime();
      if(!isValidHm(cityTime)){
        if(Date.now()-started<2500)setTimeout(attempt,25);
        return;
      }
      var changed=cityTime!==oldTime;
      if(!changed){
        if(Date.now()-started<170){
          setTimeout(attempt,25);
          return;
        }
        if(cityEl&&String(cityEl.value||'').trim()!==targetCity){
          if(Date.now()-started<2500)setTimeout(attempt,25);
          return;
        }
        if(!cityEl&&Date.now()-started<60)return;
      }
      cleanup();
      var newHour=parseInt(String(cityTime).split(':')[0],10);
      if(newHour===oldHour)replay();
      else clearOffset();
    }
    var watchEl=document.getElementById('rNowT');
    if(watchEl&&typeof MutationObserver!=='undefined'){
      observer=new MutationObserver(function(){attempt();});
      try{observer.observe(watchEl,{childList:true,characterData:true,subtree:true});}catch(_){}
    }
    setTimeout(attempt,0);
    setTimeout(attempt,16);
    setTimeout(attempt,25);
    setTimeout(attempt,32);
    setTimeout(attempt,50);
    setTimeout(attempt,80);
    setTimeout(attempt,110);
    setTimeout(attempt,130);
    setTimeout(attempt,200);
    setTimeout(attempt,320);
    setTimeout(attempt,500);
    setTimeout(attempt,750);
  }catch(_){}
}
function freezeRequestTimeDuringSave(ms){
  try{
    window.__tmRequestTimeSaveFreezeUntil=Date.now()+(Number(ms)||15000);
  }catch(_){}
}
function isRequestTimeSaveFrozen(){
  try{
    return Date.now()<Number(window.__tmRequestTimeSaveFreezeUntil||0);
  }catch(_){return false;}
}
function syncDateTimeFromBridge(){
  try{
    if(isRequestTimeSaveFrozen())return;
    var docs=getTimeCandidateDocs();
    var doc=docs[0]||document;if(!doc)return;
    var meta=readBridgeTimeMeta(doc)||{};
    for(var _mi=0;_mi<docs.length;_mi++){
      var _m2=readBridgeTimeMeta(docs[_mi])||{};
      if((!isValidHm(meta.cityTime)&&isValidHm(_m2.cityTime))||(!isValidHm(meta.reqTime)&&isValidHm(_m2.reqTime))){
        meta=_m2;
      }
    }
    meta=tmNormalizeRequestDateAfterCity(meta);
    // Вычисляем _skipTimeSync ДО applyBridgeTimeMeta чтобы не затирать rReqT во время восстановления
    var _sv=window.__tmCityChangeSave;
    if(_sv&&Date.now()-_sv.at>9000)window.__tmCityChangeSave=null;
    var _skipTimeSync=tmIsTimeSyncGuardActive();
    if(!_skipTimeSync){applyBridgeTimeMeta(meta);}else{var _nt=document.getElementById('rNowT');var _nd=document.getElementById('rNowD');if(_nt&&isValidHm(meta.cityTime))_nt.textContent=meta.cityTime;if(_nd&&meta.cityDate)_nd.textContent='('+meta.cityDate+')';updateRequestTimeBadge();}
    var dateIso=parseBridgeIsoDate(meta.reqDate||'');
    if(!dateIso){
      for(var _di=0;_di<docs.length;_di++){
        var _dateSrc=detectBridgeDateField(docs[_di]);
        if(!_dateSrc)continue;
        var _iso=parseBridgeIsoDate(_dateSrc.value||'');
        if(_iso){dateIso=_iso;break;}
      }
    }
    if(dateIso){
      var uiDate=document.getElementById('dvDate');
      if(uiDate&&uiDate.value!==dateIso){uiDate.value=dateIso;onDateChange();}
    }
    if(!_skipTimeSync){
      if(tmShouldClearUiRequestTime(meta)){
        if(tmIsCityTimeReadOnlyActive()){
          tmClearUiRequestTimeControls();
          updateRequestTimeBadge();
          updDv();
          return;
        }
        tmClearUiRequestTimeControls();
        updateRequestTimeBadge();
        updDv();
        return;
      }
      var t='';
      // 1) Время заявки из базы (лейбл/точное время) — приоритетно.
      if(isValidHm(meta.reqTime)&&meta.reqTime!=='00:00')t=meta.reqTime;
      // 2) Выбранный слот таблицы — только fallback вне смены города.
      if((!isValidHm(t)||t==='00:00')&&!tmIsCityTimeReadOnlyActive()){
        for(var _ti=0;_ti<docs.length&&!isValidHm(t);_ti++){
          t=detectSelectedTimeFromTable(docs[_ti])||'';
        }
      }
      // 3) Поле времени — последний fallback вне смены города.
      if((!isValidHm(t)||t==='00:00')&&!tmIsCityTimeReadOnlyActive()){
        for(var _si=0;_si<docs.length&&!isValidHm(t);_si++){
          var timeSrc=detectBridgeTimeField(docs[_si]);
          if(!timeSrc)continue;
          var _tv=String((timeSrc.value||'')).trim();
          if(!/^\d{2}:\d{2}$/.test(_tv) && timeSrc.tagName==='SELECT'){
            var so=timeSrc.options&&timeSrc.options[timeSrc.selectedIndex];
            var st=String(so&&so.text||'').trim();
            if(/^\d{2}:\d{2}$/.test(st))_tv=st;
          }
          if(isValidHm(_tv)&&_tv!=='00:00')t=_tv;
        }
      }
      if(/^\d{2}:\d{2}$/.test(t)){
        var uiTime=document.getElementById('dvTime');
        if(uiTime&&uiTime.value!==t)uiTime.value=t;
      }
    }else if(isValidHm(meta.reqTime)){
      var uiTime2=document.getElementById('dvTime');
      if(uiTime2&&uiTime2.value!==meta.reqTime)uiTime2.value=meta.reqTime;
    }
    if(!_skipTimeSync){syncTimeGridFromInputs();updDv();}
  }catch(e){}
}
function getHourButtonCandidates(hours){
  var out=[];
  var seenDocs=[];
  var isPlusOne=Number(hours)===1;
  var directId=isPlusOne?'actAddHour1':'actAddHour2';
  function addDoc(doc,ctx,baseScore){
    try{
      if(!doc||seenDocs.indexOf(doc)!==-1)return;
      seenDocs.push(doc);
      var score=Number(baseScore)||0;
      var wrap=doc.querySelector('#crm-permanent-buttons');
      var btn=null;
      if(wrap){
        btn=wrap.querySelector('#'+directId);
        if(btn)score+=6;
      }
      if(!btn){
        var byId=doc.getElementById(directId);
        if(byId&&(!wrap||wrap.contains(byId)))btn=byId;
      }
      if(!btn)return;
      out.push({doc:doc,ctx:ctx,btn:btn,score:score});
    }catch(_e){}
  }
  // Строгий приоритет: основной документ, потом bridge.
  addDoc(document,'main',100);
  try{addDoc(getBridgeDoc(),'bridge',50);}catch(_e2){}
  try{addDoc(window.__regionBridgeFrame&&window.__regionBridgeFrame.contentDocument,'frame',40);}catch(_e3){}
  out.sort(function(a,b){return b.score-a.score;});
  return out;
}
function clickBridgeHourButton(hours){
  try{
    function doUserLikeClick(target){
      if(!target)return false;
      if(target.disabled||String(target.getAttribute('aria-disabled')||'').toLowerCase()==='true')return false;
      return tmSingleProgrammaticClick(target,500);
    }
    var candidates=getHourButtonCandidates(hours);
    for(var i=0;i<candidates.length;i++){
      if(doUserLikeClick(candidates[i].btn)){
        try{window.__tmLastHourClickCtx=candidates[i].ctx;}catch(_){}
        tmRememberHourOffsetChoice(hours);
        tmRememberTransferManualTimeInteraction('offset_'+String(Number(hours)||0));
        scheduleHideTimeChangeReasonModal();
        return true;
      }
    }
    return false;
  }catch(e){return false;}
}
function pickTimeSlot(tv,opts){
  opts=opts||{};
  if(!opts.skipReason&&isActiveTimeReasonWorkStatusNow()){
    return runWithActiveTimeReason(function(){pickTimeSlot(tv,Object.assign({},opts,{skipReason:true}));});
  }
  const hour=document.getElementById('dvHour');
  const time=document.getElementById('dvTime');
  if(hour&&Array.from(hour.options).some((o)=>o.value===tv)){hour.value=tv;if(time)time.value='';}else if(time){time.value=tv;}
  const inp=document.getElementById('dvQuickTimeInput');
  if(inp&&tv!==undefined)inp.value=tv||'';
  if(isValidHm(String(tv||'').trim()))tmRememberTransferManualTimeInteraction(opts.fromOffset?'offset_pick':'manual_pick');
  if(opts.fromOffset){
    window.__tmActiveTimeOffsetHours=Number(opts.offsetHours)||0;
    window.__tmManualTimeSelected=false;
  }else{
    window.__tmActiveTimeOffsetHours=0;
    window.__tmTimeOffsetVisualHold=null;
    window.__tmManualTimeSelected=isValidHm(String(tv||'').trim());
    tmClearHourOffsetChoice();
  }
  window.__tmTimeExplicitlySet=true;
  syncTimeOffsetButtonsUi();
  var visibleReqTime=document.getElementById('rReqT');
  if(visibleReqTime&&isValidHm(tv))visibleReqTime.textContent=tv;
  updateRequestTimeBadge();
  window.__tmHourSyncLockUntil=0;
  syncTimeToBridgeFromUi({skipTimeCell:!!opts.skipTimeCell});
  setTimeout(syncDateTimeFromBridge,0);
  setTimeout(syncDateTimeFromBridge,120);
  scheduleHideTimeChangeReasonModal();
  if(window.__tmActiveTimeReasonChoice)scheduleApplyActiveTimeReason(window.__tmActiveTimeReasonChoice,window.__tmActiveTimeReasonApplyToken||'');
  updDv();
  syncTimeGridFromInputs();
}
function setTimeOffset(hours,opts){
  opts=opts||{};
  if(tmIsCreateRequestPage()&&!isCitySelectedUi()){syncCreatePrereqLocks();showToast('Сначала выберите город');return;}
  if(!isCitySelectedUi())return;
  tmFinishPrereqUnlockVisual(document.getElementById(Number(hours)===2?'uiAddHour2':'uiAddHour1'));
  var activeReasonMode=isActiveTimeReasonWorkStatusNow()&&!isModerationOrClarificationStatusNow();
  if(activeReasonMode){
    startActiveTimeReasonModalWait();
  }
  window.__tmCityChangeSave=null;
  window.__tmCityRestoreUntil=null;
  window.__tmTimeExplicitlySet=true;
  window.__tmManualTimeSelected=false;
  window.__tmActiveTimeOffsetHours=Number(hours)||0;
  window.__tmTimeOffsetVisualHold={hours:Number(hours)||0,until:Date.now()+1800};
  syncTimeOffsetButtonsUi();
  window.__tmHourSyncLockUntil=0;
  // Только нативный клик по кнопке базы, без локальных вычислений времени.
  if(!clickBridgeHourButton(hours)){
    window.__tmTimeOffsetVisualHold=null;
    window.__tmActiveTimeOffsetHours=0;
    syncTimeOffsetButtonsUi();
    return;
  }
  scheduleHideTimeChangeReasonModal();
  if(activeReasonMode)scheduleActiveTimeReasonModalPrompt();
  // Ждем пока CRM обновит базу, затем только читаем состояние обратно.
  setTimeout(syncDateTimeFromBridge,0);
  setTimeout(syncDateTimeFromBridge,80);
  setTimeout(syncDateTimeFromBridge,180);
  setTimeout(syncDateTimeFromBridge,350);
  setTimeout(syncTimeOffsetButtonsUi,450);
  setTimeout(syncTimeOffsetButtonsUi,900);
}
function initTimeSuggest(){
  var inp=document.getElementById('dvQuickTimeInput');if(!inp||inp.dataset.bound==='1')return;inp.dataset.bound='1';
  var drop=null;
  function host(){var h=inp.closest('.time-select-wrap')||inp.closest('.f')||inp.parentElement;if(h&&window.getComputedStyle(h).position==='static')h.style.position='relative';return h||document.body;}
  function closeDrop(instant){if(drop){var _d=drop;drop=null;if(instant){if(_d.parentNode)_d.remove();if(!drop)toggleDropdownCardByInput(inp,false);}else{animateDropdownClose(_d,function(){if(_d.parentNode)_d.remove();if(!drop)toggleDropdownCardByInput(inp,false);});}}else{toggleDropdownCardByInput(inp,false);}}
  bindSingleDropdownCloser(inp,function(){closeDrop(true);});
  function parseHmToMinutes(v){
    var t=String(v||'').trim();
    var m=t.match(/^(\d{1,2}):(\d{2})$/);
    if(!m)return null;
    var hh=Number(m[1]),mm=Number(m[2]);
    if(!(hh>=0&&hh<=23&&mm>=0&&mm<=59))return null;
    return hh*60+mm;
  }
  function getClosestTimeSlotIndex(raw){
    var minutes=parseHmToMinutes(raw);
    if(minutes===null)return -1;
    var best=-1,bestDiff=1e9;
    for(var i=0;i<timeSlotValues.length;i++){
      var slotMinutes=parseHmToMinutes(timeSlotValues[i]);
      if(slotMinutes===null)continue;
      var diff=Math.abs(slotMinutes-minutes);
      if(diff<bestDiff){bestDiff=diff;best=i;}
      if(diff===0)return i;
    }
    return best;
  }
  function scrollDropToCurrent(){
    if(!drop)return;
    var current=(inp.value||'').trim();
    if(!current)return;
    var idx=timeSlotValues.indexOf(current);
    if(idx<0)idx=getClosestTimeSlotIndex(current);
    if(idx<0)return;
    var items=drop.querySelectorAll('.tm-name-suggest-item');
    var item=items&&items[idx];
    if(!item)return;
    var top=Math.max(0,item.offsetTop-(drop.clientHeight/2)+(item.offsetHeight/2));
    var maxTop=Math.max(0,drop.scrollHeight-drop.clientHeight);
    drop.scrollTop=Math.max(0,Math.min(top,maxTop));
  }
  function showDrop(){
    if(tmIsForeignWorkLocked())return;
    if(tmIsCreateRequestPage()&&!isCitySelectedUi()){syncCreatePrereqLocks();showToast('Сначала выберите город');return;}
    tmFinishPrereqUnlockVisual(inp);
    requestSingleDropdownOpen(inp);
    closeDrop();
    drop=document.createElement('div');
    drop.className='tm-name-suggest-dropdown time-suggest-dropdown';
    drop.style.boxSizing='border-box';
    drop.style.maxHeight='260px';
    drop.style.zIndex='10000010';
    var current=(inp.value||'').trim();
    timeSlotValues.forEach(function(tv){
      var btn=document.createElement('button');
      btn.type='button';
      btn.className='tm-name-suggest-item'+(current===tv?' is-selected':'');
      var tx=document.createElement('span');
      tx.className='tm-name-suggest-text';
      tx.textContent=tv;
      btn.appendChild(tx);
      btn.addEventListener('mousedown',function(e){e.preventDefault();});
      btn.addEventListener('click',function(){pickTimeSlot(tv);closeDrop();});
      drop.appendChild(btn);
    });
    host().appendChild(drop);
    positionDropdownInHost(drop,inp,host(),3);
    var iw=Math.round(inp.offsetWidth||parseFloat(window.getComputedStyle(inp).width)||0);
    if(iw>0){
      var px=iw+'px';
      drop.style.setProperty('width',px,'important');
      drop.style.setProperty('min-width',px,'important');
      drop.style.setProperty('max-width',px,'important');
    }
    toggleDropdownCardByInput(inp,true);
    requestAnimationFrame(function(){requestAnimationFrame(scrollDropToCurrent);});
  }
  function toggleDrop(){if(drop){closeDrop();return;}showDrop();}
  inp.addEventListener('pointerdown',function(e){e.preventDefault();blurActiveEditableField(inp);toggleDrop();});
  inp.addEventListener('keydown',function(e){if(e.key==='Escape'){closeDrop();return;}if(e.key==='Enter'||e.key===' '||e.key==='ArrowDown'){e.preventDefault();toggleDrop();}});
  inp.addEventListener('blur',function(){setTimeout(closeDrop,20);});
  document.addEventListener('pointerdown',function(e){if(!drop)return;if(e.target===inp)return;if(drop.contains(e.target))return;closeDrop();},true);
}
