function ensureOpenCustomerCardLiveBorder(a){
  if(!a)return;
  var oldSvg=a.querySelector&&a.querySelector(':scope > svg.tm-client-card-live-border');
  if(oldSvg&&oldSvg.parentNode)oldSvg.parentNode.removeChild(oldSvg);
  var canvas=a.querySelector&&a.querySelector(':scope > canvas.tm-client-card-live-border');
  var state=a.__tmClientCardLiveBorderState;
  if(!canvas){
    canvas=document.createElement('canvas');
    canvas.className='tm-client-card-live-border';
    canvas.setAttribute('aria-hidden','true');
    a.appendChild(canvas);
  }
  if(!state||state.canvas!==canvas||!state.ctx){
    state={
      canvas:canvas,
      ctx:canvas.getContext('2d'),
      count:7,
      length:0,
      period:0,
      segmentLength:0,
      startedAt:performance.now(),
      lastPaint:0,
      geomKey:'',
      x:0,
      y:0,
      width:0,
      height:0,
      radius:0,
      topLength:0,
      sideLength:0,
      arcLength:0
    };
    a.__tmClientCardLiveBorderState=state;
  }
  function pointAt(distance){
    var length=state.length;
    var normalized=((distance%length)+length)%length;
    var x=state.x;
    var y=state.y;
    var right=x+state.width;
    var bottom=y+state.height;
    var radius=state.radius;
    var straightX=state.topLength;
    var straightY=state.sideLength;
    var arc=state.arcLength;
    function arcPoint(cx,cy,startAngle,offset){
      var angle=startAngle+offset/radius;
      return{x:cx+Math.cos(angle)*radius,y:cy+Math.sin(angle)*radius};
    }
    if(normalized<=straightX)return{x:x+radius+normalized,y:y};
    normalized-=straightX;
    if(normalized<=arc)return arcPoint(right-radius,y+radius,-Math.PI/2,normalized);
    normalized-=arc;
    if(normalized<=straightY)return{x:right,y:y+radius+normalized};
    normalized-=straightY;
    if(normalized<=arc)return arcPoint(right-radius,bottom-radius,0,normalized);
    normalized-=arc;
    if(normalized<=straightX)return{x:right-radius-normalized,y:bottom};
    normalized-=straightX;
    if(normalized<=arc)return arcPoint(x+radius,bottom-radius,Math.PI/2,normalized);
    normalized-=arc;
    if(normalized<=straightY)return{x:x,y:bottom-radius-normalized};
    normalized-=straightY;
    return arcPoint(x+radius,y+radius,Math.PI,Math.min(arc,normalized));
  }
  function paint(now,force){
    if(!state.length||!state.ctx)return;
    if(!force&&now-state.lastPaint<33)return;
    state.lastPaint=now;
    var phase=(((now-state.startedAt)%18000)+18000)%18000/18000*state.length;
    var ctx=state.ctx;
    ctx.clearRect(0,0,state.canvas.width,state.canvas.height);
    ctx.save();
    ctx.setTransform(state.pixelRatio,0,0,state.pixelRatio,0,0);
    ctx.beginPath();
    for(var index=0;index<state.count;index++){
      var start=phase+index*state.period;
      var steps=Math.max(8,Math.ceil(state.segmentLength/1.2));
      for(var step=0;step<=steps;step++){
        var point=pointAt(start+state.segmentLength*(step/steps));
        if(step===0)ctx.moveTo(point.x,point.y);
        else ctx.lineTo(point.x,point.y);
      }
    }
    ctx.strokeStyle='rgba(24,95,165,.76)';
    ctx.lineWidth=1.28;
    ctx.lineCap='butt';
    ctx.lineJoin='round';
    ctx.stroke();
    ctx.restore();
  }
  function animate(now){
    if(!a.isConnected||a.classList.contains('is-disabled')){
      a.__tmClientCardLiveBorderFrame=0;
      return;
    }
    paint(now,false);
    a.__tmClientCardLiveBorderFrame=requestAnimationFrame(animate);
  }
  function sync(){
    try{
      var buttonWidth=Math.max(1,a.offsetWidth||a.clientWidth||1);
      var buttonHeight=Math.max(1,a.offsetHeight||a.clientHeight||1);
      var geomKey=buttonWidth.toFixed(2)+'x'+buttonHeight.toFixed(2);
      if(state.geomKey===geomKey)return;
      var stroke=1.28;
      var outside=.7;
      var pad=2;
      var w=Math.max(1,buttonWidth+pad*2);
      var h=Math.max(1,buttonHeight+pad*2);
      var pixelRatio=Math.max(1,Math.min(2,window.devicePixelRatio||1));
      canvas.width=Math.max(1,Math.round(w*pixelRatio));
      canvas.height=Math.max(1,Math.round(h*pixelRatio));
      state.pixelRatio=pixelRatio;
      var x=pad-outside+stroke/2;
      var y=pad-outside+stroke/2;
      var rw=Math.max(1,buttonWidth+outside*2-stroke);
      var rh=Math.max(1,buttonHeight+outside*2-stroke);
      var r=Math.max(1,Math.min(8.5,buttonHeight/2-1.2));
      state.x=x;
      state.y=y;
      state.width=rw;
      state.height=rh;
      state.radius=r;
      state.topLength=Math.max(0,rw-r*2);
      state.sideLength=Math.max(0,rh-r*2);
      state.arcLength=Math.PI*r/2;
      state.length=Math.max(1,state.topLength*2+state.sideLength*2+state.arcLength*4);
      state.period=state.length/state.count;
      state.segmentLength=state.period*.5;
      state.geomKey=geomKey;
      paint(performance.now(),true);
    }catch(_){}
  }
  sync();
  if(!a.__tmClientCardLiveBorderResize&&window.ResizeObserver){
    try{
      a.__tmClientCardLiveBorderResize=new ResizeObserver(sync);
      a.__tmClientCardLiveBorderResize.observe(a);
    }catch(_){}
  }
  if(!a.__tmClientCardLiveBorderFrame&&!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)){
    a.__tmClientCardLiveBorderFrame=requestAnimationFrame(animate);
  }else if(!a.__tmClientCardLiveBorderFrame){
    paint(performance.now(),true);
  }
}
function setOpenCustomerCardButtonUrl(url){
  var a=document.getElementById('tmOpenCustomerCardBtn');
  if(!a)return;
  var href=String(url||'').trim();
  if(href&&href.charAt(0)==='/'){
    try{href=new URL(href,window.location.origin).href;}catch(_e){}
  }
  if(href){
    a.href=href;
    a.classList.remove('is-disabled');
    a.setAttribute('aria-disabled','false');
    ensureOpenCustomerCardLiveBorder(a);
  }else{
    a.removeAttribute('href');
    a.classList.add('is-disabled');
    a.setAttribute('aria-disabled','true');
    var border=a.querySelector&&a.querySelector(':scope > .tm-client-card-live-border');
    if(border&&border.parentNode)border.parentNode.removeChild(border);
    if(a.__tmClientCardLiveBorderResize){
      try{a.__tmClientCardLiveBorderResize.disconnect();}catch(_e){}
      a.__tmClientCardLiveBorderResize=null;
    }
    if(a.__tmClientCardLiveBorderFrame){
      try{cancelAnimationFrame(a.__tmClientCardLiveBorderFrame);}catch(_e){}
      a.__tmClientCardLiveBorderFrame=0;
    }
    a.__tmClientCardLiveBorderState=null;
    a.__tmClientCardLiveBorderGeom=null;
  }
}
function getBridgeSaveCardState(doc){
  if(!doc)return null;
  var saveAction=doc.getElementById('newCustomerSaveAction')||doc.querySelector('#newCustomerSaveAction');
  var infoLinkEl=doc.querySelector('#customerInfoLink > a[href*="/admin/domain/customer/update?id="], #customerInfoLink a[href*="/admin/domain/customer/update?id="]');
  var infoHref=infoLinkEl?String(infoLinkEl.getAttribute('href')||'').trim():'';
  var txt=String((saveAction&&(saveAction.innerText||saveAction.textContent))||'').replace(/\s+/g,' ').trim().toLowerCase();
  var cls=String((saveAction&&saveAction.className)||'').toLowerCase();
  var aria=String((saveAction&&saveAction.getAttribute&&saveAction.getAttribute('aria-disabled'))||'').toLowerCase();
  var disabled=!!(saveAction&&saveAction.disabled)||aria==='true'||cls.indexOf('disabled')!==-1;
  var asksCity=txt.indexOf('выберите город')!==-1;
  var saveText=txt.indexOf('сохранить карточку')!==-1;
  // Bridge может оставлять подпись "(выберите город)" даже в реально кликабельном состоянии.
  // Поэтому истинный критерий готовности: нет disabled и есть текст "Сохранить карточку".
  var clickable=!!saveAction&&saveText;
  var active=clickable&&!disabled;
  var visible=false;
  try{
    if(saveAction&&saveAction.isConnected){
      var win=(doc.defaultView||window);
      var cs=win.getComputedStyle?win.getComputedStyle(saveAction):null;
      var r=saveAction.getBoundingClientRect();
      visible=(!cs||cs.display!=='none')&&(!cs||cs.visibility!=='hidden')&&r.width>0&&r.height>0;
    }
  }catch(_){}
  return {saveAction:saveAction,infoHref:infoHref,disabled:disabled,asksCity:asksCity,active:active,clickable:clickable,visible:visible,text:txt};
}
