function bindSaveCardDirtyWatchers(){
  if(__saveCardDirtyBindDone)return;
  var card=document.getElementById('tmClientCard');
  if(!card)return;
  __saveCardDirtyBindDone=true;
  function shouldTrackTarget(target){
    if(!target||!target.closest)return false;
    if(target.closest('.btn-save-card'))return false;
    var ctl=target.closest('input,textarea,select,button');
    if(!ctl)return false;
    return card.contains(ctl);
  }
  function onTrustedChange(e){
    if(!e||!e.isTrusted)return;
    if(!shouldTrackTarget(e.target))return;
    markSaveCardDirty();
  }
  card.addEventListener('input',onTrustedChange,true);
  card.addEventListener('change',onTrustedChange,true);
  card.addEventListener('click',onTrustedChange,true);
}
function getNativeCsrfPair(){
  var param='';
  var token='';
  try{param=(document.querySelector('meta[name="csrf-param"]')||{}).content||'';}catch(_){}
  try{token=(document.querySelector('meta[name="csrf-token"]')||{}).content||'';}catch(_){}
  try{
    if(param&&!token){
      var inp=document.querySelector('input[name="'+param+'"]');
      if(inp)token=String(inp.value||'');
    }
  }catch(_){}
  if(!param)param='_csrf-frontend';
  try{
    if(!token){
      var inp2=document.querySelector('input[name="'+param+'"]');
      if(inp2)token=String(inp2.value||'');
    }
  }catch(_){}
  return {param:String(param||'_csrf-frontend'),token:String(token||'')};
}
