function setNativeTextareasInDoc(doc,selectors,value,opts){
  opts=opts||{};
  if(!doc)return false;
  var nodes=Array.from(doc.querySelectorAll(selectors||''));
  if(!nodes.length)return false;
  var changedAny=false;
  nodes.forEach(function(el){
    if(!el)return;
    var prev=String(el.value||'');
    var next=String(value||'');
    var changed=(prev!==next);
    if(changed)el.value=next;
    if(changed||opts.forceNotify){
      try{el.dispatchEvent(new Event('input',{bubbles:true}));}catch(_e1){}
      try{el.dispatchEvent(new Event('change',{bubbles:true}));}catch(_e2){}
    }
    if(opts.forceBlur){
      try{el.dispatchEvent(new Event('blur',{bubbles:true}));}catch(_e4){}
    }
    if(changed)changedAny=true;
  });
  return changedAny;
}
function ensureServiceCommentSubmitOverride(form,opts){
  opts=opts||{};
  try{
    if(!form||!form.appendChild)return false;
    try{syncIntercomCodeToServiceComment();}catch(_e0){}
    var serviceField=getUiServiceCommentField();
    if(!serviceField)return false;
    var serviceVal=String(serviceField.value||'');
    var names=['CustomerRequest[comments_service]','CustomerRequest[comment_service]','comments_service','comment_service'];
    try{
      getBridgeServiceCommentTargets().forEach(function(el){
        var nm=String((el&&el.name)||'').trim();
        if(nm&&names.indexOf(nm)===-1)names.unshift(nm);
      });
    }catch(_e1){}
    var controls=[];
    try{controls=Array.from(form.elements||[]);}catch(_e2){controls=[];}
    names.forEach(function(name){
      controls.forEach(function(el){
        if(!el||String(el.name||'')!==name||!('value' in el))return;
        if(String(el.value||'')!==serviceVal)el.value=serviceVal;
        if(opts.forceNotify){
          try{el.dispatchEvent(new Event('input',{bubbles:true}));}catch(_e3){}
          try{el.dispatchEvent(new Event('change',{bubbles:true}));}catch(_e4){}
        }
        if(opts.forceBlur){
          try{el.dispatchEvent(new Event('blur',{bubbles:true}));}catch(_e5){}
        }
      });
      var key='tm-submit-override-'+name.replace(/[^\w-]+/g,'_');
      var hidden=null;
      try{hidden=form.querySelector('input[type="hidden"][data-tm-submit-comment-override="'+key+'"]');}catch(_e6){}
      if(!hidden){
        hidden=(form.ownerDocument||document).createElement('input');
        hidden.type='hidden';
        hidden.setAttribute('data-tm-submit-comment-override',key);
        form.appendChild(hidden);
      }else if(hidden.parentNode===form){
        // Держим override последним полем формы: при дублях имени PHP/Yii берёт последнее значение.
        form.appendChild(hidden);
      }
      hidden.name=name;
      hidden.value=serviceVal;
    });
    return true;
  }catch(_e){return false;}
}
