function ensureCreateLoadingInBodyForDisplay(el){
  if(!el)return el;
  try{
    var holder=document.getElementById('tmCrmFormHolder');
    var inHolder=!!(holder&&holder.contains(el));
    if(inHolder&&(document.body||document.documentElement)){
      (document.body||document.documentElement).appendChild(el);
    }
  }catch(_eMove){}
  return el;
}
function applyCreateLoadingInlineFallback(el){
  if(!el)return;
  // Только страховка контейнера (видимость/слой), без изменения внешнего вида
  // самого спиннера: оставляем оригинальный CSS v11.
  el.style.position='fixed';
  el.style.left='0';
  el.style.top='0';
  el.style.right='0';
  el.style.bottom='0';
  el.style.inset='0';
  el.style.zIndex='10000090';
  el.style.display='flex';
  el.style.alignItems='center';
  el.style.justifyContent='center';
  el.style.background='rgba(20,24,30,.18)';
  el.style.pointerEvents='auto';
  var wrap=el.querySelector('.tm-create-loading-spinner-wrap');
  var spin=el.querySelector('.tm-create-loading-spinner');
  if(wrap)wrap.removeAttribute('style');
  if(spin){
    try{
      if(spin.__tmFallbackSpinAnim&&typeof spin.__tmFallbackSpinAnim.cancel==='function'){
        spin.__tmFallbackSpinAnim.cancel();
      }
    }catch(_eAnim){}
    try{delete spin.__tmFallbackSpinAnim;}catch(_eDel){spin.__tmFallbackSpinAnim=null;}
    spin.removeAttribute('style');
  }
}
function showCreateLoading(forceInstant){
  var el=ensureCreateLoadingUi();
  el=ensureCreateLoadingInBodyForDisplay(el);
  applyCreateLoadingInlineFallback(el);
  // Сбрасываем инлайн-оверрайды, чтобы работала штатная мягкая CSS-анимация.
  el.style.opacity='';
  el.style.visibility='';
  if(forceInstant===true){
    // Аварийный режим: быстрый мягкий fade вместо резкого "всплеска".
    el.style.transition='opacity .18s cubic-bezier(.22,.61,.36,1),visibility 0s linear 0s';
    if(!el.classList.contains('open')){
      el.classList.remove('open');
      void el.offsetWidth;
    }
    el.classList.add('open');
  }else{
    el.style.transition='';
    if(!el.classList.contains('open')){
      el.classList.remove('open');
      void el.offsetWidth;
      el.classList.add('open');
    }
  }
  if(__createLoadingTimer){clearTimeout(__createLoadingTimer);__createLoadingTimer=0;}
}
function hideCreateLoading(force){
  if(__tmCustomerCardSaveLoadingDepth>0)return;
  if(!force&&(__createLoadingArmed||Date.now()<__createLoadingLockUntil))return;
  disarmCreateLoadingOnNavigate();
  var el=document.getElementById('tmCreateLoading');
  if(el){
    el.classList.remove('open');
    // replacePage() пересобирает head и может временно удалить CSS спиннера.
    // Поэтому скрытие дублируем инлайном, чтобы оверлей не оставался видимым
    // на уже открытой странице после перехода.
    el.style.opacity='0';
    el.style.visibility='hidden';
    el.style.pointerEvents='none';
    el.style.transition=force?'none':'';
    if(force){
      setTimeout(function(){
        try{
          if(!__createLoadingArmed&&!el.classList.contains('open'))el.style.transition='';
        }catch(_){}
      },40);
    }
  }
  if(__createLoadingTimer){clearTimeout(__createLoadingTimer);__createLoadingTimer=0;}
}
function hideCreateLoadingIfIdle(){
  if(__createLoadingArmed||Date.now()<__createLoadingLockUntil)return;
  hideCreateLoading(true);
}
function shouldArmLoadingForSubmitButton(btn){
  try{
    if(!btn)return false;
    var tag=String(btn.tagName||'').toLowerCase();
    var type=String((btn.getAttribute&&btn.getAttribute('type'))||btn.type||'').toLowerCase();
    if(tag==='input'&&type!=='submit')return false;
    if(tag==='button'&&type!=='submit')return false;
    var txt=String(btn.textContent||btn.value||'').toLowerCase().replace(/\s+/g,' ').trim();
    if(!txt)return false;
    if(txt.indexOf('созд')===-1&&txt.indexOf('сохран')===-1&&txt.indexOf('уточнен')===-1)return false;
    return true;
  }catch(_){return false;}
}
var __nativeSubmitLoadingHooksInstalled=false;
function installNativeSubmitLoadingHooks(){
  if(__nativeSubmitLoadingHooksInstalled)return;
  __nativeSubmitLoadingHooksInstalled=true;
  document.addEventListener('submit',function(e){
    try{
      if(!e||e.isTrusted!==true)return;
      if(e.defaultPrevented)return;
      var form=e&&e.target;
      if(!form||!form.getAttribute)return;
      if(form.closest&&form.closest('#timeChangeReasonModal'))return;
      var id=String(form.id||'').toLowerCase();
      var act=String(form.getAttribute('action')||'').toLowerCase();
      if(id.indexOf('customerrequestform')===-1&&act.indexOf('/customer-request/')===-1)return;
      try{forceSyncCommentsToNativeFields({forceNotify:true,forceBlur:true});}catch(_){}
      try{freezeRequestTimeDuringSave(15000);}catch(_){}
      try{queueRequestSaveNotice('нативная форма CRM');}catch(_){}
      try{armCreateLoadingOnNavigate();}catch(_){try{showCreateLoading();}catch(__){}}
    }catch(_e){}
  },false);
}
async function runCreateSubmit(flowText){
  if(__tmCreateSubmitBusy)return false;
  __tmCreateSubmitBusy=true;
  setCreateSubmitUiLocked(true);
  var submitStarted=false;
  try{
    freezeRequestTimeDuringSave(15000);
    suppressBeforeUnload(15000);
    flushOzvToComment();
    flushAllToBridge();
    // Дожимаем комментарии в нативные поля прямо перед отправкой.
    try{
      var _cVal=(getUiMainCommentField()||{}).value||'';
      var _sVal=(getUiServiceCommentField()||{}).value||'';
      syncSourceComment(_cVal,0,{forceNotify:true,forceBlur:true});
      syncSourceServiceComment(_sVal,0,{forceBlur:true});
      // Жёстко пишем комментарии во все нативные поля CRM (main+bridge),
      // чтобы submit не ушёл с пустыми полями из-за гонки синка.
      forceSyncCommentsToNativeFields({forceNotify:true,forceBlur:true});
    }catch(_e_sync){}
    // Карточку клиента сохраняем перед созданием только если клиентские поля реально изменились.
    var shouldSaveCustomerUpdate=false;
    try{shouldSaveCustomerUpdate=customerUpdateNeedsSaveBeforeCreate();}catch(_e_need_save){shouldSaveCustomerUpdate=false;}
    if(shouldSaveCustomerUpdate){
      try{
        // На create с customer_id сначала гарантированно завершаем обновление
        // существующей карточки, и только потом отправляем саму заявку.
        try{showCreateLoading(true);}catch(_e_loading){}
        await saveCustomerUpdateFromUiIfNeeded({keepalive:true});
      }catch(saveErr){
        console.warn('[CRM v11] customer update save before submit failed:',saveErr&&saveErr.message?saveErr.message:saveErr);
        try{disarmCreateLoadingOnNavigate();hideCreateLoading(true);}catch(_e_hide){}
        try{
          var saveMsg=String((saveErr&&saveErr.message)||saveErr||'');
          if(saveMsg.indexOf('duplicate_phone_customer:')!==0)showToast('Не удалось сохранить карточку клиента');
        }catch(_e_toast){}
        return;
      }
    }
    // Повторная дожимка комментариев непосредственно перед кликом по submit.
    forceSyncCommentsToNativeFields({forceNotify:true,forceBlur:true});
    var queuedFirstCreatePhoneCheck=false;
    if(!__isUpdatePage&&!getCreateCustomerId()){
      try{queuedFirstCreatePhoneCheck=tmQueueFirstCreatePhoneCheck();}catch(_){}
    }
    var okSubmit=clickBridgeSubmit(flowText);
    if(okSubmit){
      submitStarted=true;
      try{queueRequestSaveNotice('bridge submit');}catch(_){}
      armCreateLoadingSafe();
      return true;
    }
    if(!okSubmit){
      if(queuedFirstCreatePhoneCheck)tmClearFirstCreatePhoneCheck();
      try{disarmCreateLoadingOnNavigate();hideCreateLoading(true);}catch(_e_hide_submit){}
      if(typeof showToast==='function')showToast('Не удалось отправить форму CRM');
      return false;
    }
  }catch(submitErr){
    console.warn('[CRM v11] create submit failed:',submitErr&&submitErr.message?submitErr.message:submitErr);
    try{disarmCreateLoadingOnNavigate();hideCreateLoading(true);}catch(_e_hide_unexpected){}
    try{if(typeof showToast==='function')showToast('Не удалось отправить форму CRM');}catch(_e_toast_unexpected){}
    return false;
  }finally{
    if(!submitStarted){
      __tmCreateSubmitBusy=false;
      setCreateSubmitUiLocked(false);
    }
  }
}
function handleSave(){
  if(!tmValidateRequiredBeforeRequestAction())return;
  var phone=document.querySelector('#phList input[type="tel"]');
  if(!phone||!phone.value.trim()){phone.focus();phone.style.borderColor='var(--rd)';setTimeout(function(){phone.style.borderColor='';},2000);return;}
  runCreateSubmit('Создать');
}
function handleClarify(){
  if(!tmValidateRequiredBeforeRequestAction())return;
  if(!tmCanSubmitClarifyByTimeGap())return;
  runCreateSubmit('На уточнение');
}

