    function __tmCleanDispatcherName(raw){
      var s=String(raw||'').replace(/\s+/g,' ').trim();
      s=s.replace(/^.*?Диспетчер\s+Кол[\s-]*Центра\s*[-:]\s*/i,'');
      s=s.replace(/^.*?Заявка\s+в\s+работе\s+у\s*/i,'');
      s=s.replace(/^у\s+/i,'').replace(/[.;,]+$/,'').trim();
      return s;
    }
    function __tmReadDispatcherFromDoc(doc){
      try{
        doc=doc||document;
        var direct=doc.querySelector('#navbarSupportedContent .header-user-info .text-nowrap:nth-of-type(2)');
        var txt=direct?String(direct.textContent||'').trim():'';
        if(/Диспетчер\s+Кол[\s-]*Центра/i.test(txt))return __tmCleanDispatcherName(txt);
        var nodes=Array.from(doc.querySelectorAll('#navbarSupportedContent .header-user-info .text-nowrap, #navbarSupportedContent .header-user-info small, .header-user-info .text-nowrap, .header-user-info small'));
        for(var i=0;i<nodes.length;i++){
          txt=String(nodes[i].textContent||'').replace(/\s+/g,' ').trim();
          if(/Диспетчер\s+Кол[\s-]*Центра/i.test(txt))return __tmCleanDispatcherName(txt);
        }
      }catch(_){}
      return '';
    }
    function __tmDispatcherKey(v){
      return __tmCleanDispatcherName(v).toLowerCase().replace(/ё/g,'е').replace(/[^а-яa-z\s]/g,' ').replace(/\s+/g,' ').trim();
    }
    function __tmDispatcherProfile(v){
      var key=__tmDispatcherKey(v);
      var words=key.match(/[а-яa-z]+/g)||[];
      return {
        key:key,
        last:words[0]||'',
        initials:words.slice(1).map(function(w){return w.charAt(0)||'';}).filter(Boolean)
      };
    }
    function __tmSameDispatcher(a,b){
      var ak=__tmDispatcherKey(a),bk=__tmDispatcherKey(b);
      if(!ak||!bk)return false;
      if(ak===bk)return true;
      var ap=__tmDispatcherProfile(a),bp=__tmDispatcherProfile(b);
      if(!ap.last||!bp.last||ap.last!==bp.last)return false;
      if(ap.initials.length&&bp.initials.length)return ap.initials[0]===bp.initials[0];
      return true;
    }
    function __tmResolveCurrentDispatcher(opts){
      opts=opts||{};
      if(window.__tmCurrentDispatcherName)return Promise.resolve(window.__tmCurrentDispatcherName);
      if(window.__tmCurrentDispatcherPromise)return window.__tmCurrentDispatcherPromise;
      var direct=__tmReadDispatcherFromDoc(document);
      if(direct){
        window.__tmCurrentDispatcherName=direct;
        try{sessionStorage.setItem('__tm_current_dispatcher_name_v11',direct);}catch(_){}
        return Promise.resolve(direct);
      }
      var cached='';
      try{cached=sessionStorage.getItem('__tm_current_dispatcher_name_v11')||'';}catch(_){}
      if(opts.noFetch)return Promise.resolve(cached||'');
      window.__tmCurrentDispatcherPromise=fetch('/admin/domain/customer-request/index',{credentials:'include',cache:'no-store'})
        .then(function(r){return r&&r.ok?r.text():'';})
        .then(function(html){
          var name='';
          try{
            var doc=new DOMParser().parseFromString(String(html||''),'text/html');
            name=__tmReadDispatcherFromDoc(doc);
          }catch(_){}
          if(name){
            window.__tmCurrentDispatcherName=name;
            try{sessionStorage.setItem('__tm_current_dispatcher_name_v11',name);}catch(_){}
            return name;
          }
          return cached||'';
        })
        .catch(function(){return cached||'';});
      return window.__tmCurrentDispatcherPromise;
    }
    var currentDispatcherPromise=__tmResolveCurrentDispatcher({noFetch:true});
    function __tmIsTextLikeControl(el){
      try{
        var tag=String(el&&el.tagName||'').toLowerCase();
        var type=String(el&&el.type||'').toLowerCase();
        if(tag==='textarea')return true;
        if(tag!=='input')return false;
        return !/^(hidden|button|submit|reset|checkbox|radio|file|range|color)$/i.test(type);
      }catch(_){return false;}
    }
    function __tmMarkReadonlyTextCopyable(el){
      if(!el)return;
      try{
        if(document.body&&document.body.classList.contains('tm-closed-readonly-mode')&&el.matches&&el.matches('#dvQuickTimeInput')){
          el.readOnly=true;
          el.setAttribute('readonly','readonly');
          el.tabIndex=-1;
          el.style.setProperty('pointer-events','none','important');
          el.style.setProperty('cursor','not-allowed','important');
          el.style.setProperty('user-select','none','important');
          el.style.setProperty('-webkit-user-select','none','important');
          return;
        }
      }catch(_){}
      try{if(el.dataset&&el.dataset.tmReadonlyCopyable==='1')return;}catch(_){}
      try{if('disabled' in el)el.disabled=false;}catch(_){}
      try{el.removeAttribute('disabled');}catch(_){}
      try{el.removeAttribute('aria-disabled');}catch(_){}
      try{el.tabIndex=0;}catch(_){}
      try{
        el.style.setProperty('pointer-events','auto','important');
        el.style.setProperty('cursor','text','important');
        el.style.setProperty('user-select','text','important');
        el.style.setProperty('-webkit-user-select','text','important');
      }catch(_){}
      try{if(el.dataset)el.dataset.tmReadonlyCopyable='1';}catch(_){}
    }
