    function __tmIsCopyGestureEvent(e){
      try{
        var type=String(e&&e.type||'');
        if(/^(pointerdown|mousedown|mouseup|selectstart|contextmenu|copy)$/.test(type))return true;
        if(type==='keydown'){
          if(!(e.ctrlKey||e.metaKey))return false;
          var k=String(e.key||'').toLowerCase();
          var code=String(e.code||'').toLowerCase();
          return k==='c'||k==='a'||k==='insert'||code==='keyc'||code==='keya'||code==='insert';
        }
      }catch(_){}
      return false;
    }
