    function __tmLockFormControl(el,hardLock){
      if(!el)return;
      var tag=String(el.tagName||'').toLowerCase();
      var type=String(el.type||'').toLowerCase();
      var textLike=__tmIsTextLikeControl(el);
      if(tag==='input'&&type==='hidden')return;
      if(el.closest&&el.closest('#tmActiveClaimBtn,#_claimOverlay,#_claimPalette,#_nfOverlay,#_nfPalette,#tmClosedActionBar,.tm-closed-action-btn,[data-tm-closed-native-action="1"]'))return;
      try{if(el.dataset.tmForeignLock!=='1')el.dataset.tmForeignLock='1';}catch(_){}
      try{if(!textLike&&el.getAttribute('aria-disabled')!=='true')el.setAttribute('aria-disabled','true');}catch(_){}
      if(!hardLock&&tag==='input'&&(type==='date'||type==='button'||type==='submit'||type==='reset'||type==='checkbox'||type==='radio'||type==='file')){
        try{if(el.tabIndex!==-1)el.tabIndex=-1;}catch(_){}
        return;
      }
      if(!hardLock&&(tag==='button'||tag==='select')){
        try{if(el.tabIndex!==-1)el.tabIndex=-1;}catch(_){}
        return;
      }
      if(tag==='input'||tag==='textarea'){
        try{if(!el.readOnly)el.readOnly=true;}catch(_){}
        try{if(!el.hasAttribute('readonly'))el.setAttribute('readonly','readonly');}catch(_){}
        if(textLike)__tmMarkReadonlyTextCopyable(el);
        try{
          if(el.classList&&el.classList.contains('phone-short')){
            el.classList.remove('tm-readonly-stripe');
            el.removeAttribute('data-tm-stripe-readonly');
            el.removeAttribute('data-tm-foreign-lock');
            el.removeAttribute('aria-disabled');
            el.style.removeProperty('background-image');
            el.style.removeProperty('background-color');
          }else{
            applyTmReadonlyStripe(el);
          }
        }catch(_){}
        if(type==='checkbox'||type==='radio'||type==='file'||type==='button'||type==='submit'){
          try{if(!el.disabled)el.disabled=true;}catch(_){}
          try{if(!el.hasAttribute('disabled'))el.setAttribute('disabled','disabled');}catch(_){}
        }
      }else if(tag==='select'||tag==='button'){
        try{if(!el.disabled)el.disabled=true;}catch(_){}
        try{if(!el.hasAttribute('disabled'))el.setAttribute('disabled','disabled');}catch(_){}
      }
      try{if(textLike)__tmMarkReadonlyTextCopyable(el);else if(el.tabIndex!==-1)el.tabIndex=-1;}catch(_){}
    }
    function __tmPaintInWorkCard(currentName){
      var card=document.getElementById('tmInWorkStateCard');
      if(!card||!isInWork||!inWorkWho||!currentName)return;
      var mine=__tmSameDispatcher(currentName,inWorkWho);
      var darkTheme=!!(document.documentElement&&document.documentElement.classList.contains('tm-v11-dark'));
      var bd=card.querySelector('.card-bd')||card;
      var label=card.querySelector('[data-tm-work-label]');
      var who=card.querySelector('[data-tm-work-owner]');
      card.classList.toggle('tm-in-work-mine',mine);
      card.classList.toggle('tm-in-work-other',!mine);
      var bg=darkTheme?(mine?'#203627':'#3F2427'):(mine?'#f4fff6':'#fff4f1');
      card.style.borderColor=darkTheme?(mine?'#416F4B':'#7E484E'):(mine?'#9bd5a6':'#efb0a4');
      card.style.background=bg;
      bd.style.background=bg;
      if(label)label.style.color=darkTheme?(mine?'#A9DFB1':'#FFB3BA'):(mine?'#1f7a37':'#b42318');
      if(who)who.style.color=darkTheme?(mine?'#8FC99A':'#E799A0'):(mine?'#2e7d32':'#9f2d19');
      card.title=mine?'Заявка в работе у текущего диспетчера':'Заявка в работе у другого диспетчера';
    }
