    if(nfContDetached){nfContDetached.style.cssText='display:none!important';document.body.appendChild(nfContDetached);}
    if(nativeNotAnswerBtn){nativeNotAnswerBtn.style.cssText='position:fixed;left:-9999px;top:-9999px;opacity:0;pointer-events:none;';document.body.appendChild(nativeNotAnswerBtn);}
