            el.classList.remove(oldCls,cls);
            el.style.setProperty('--tm-ro-stripe',unlocking?'1':'0','important');
            el.style.setProperty('background-color',darkTheme?(isDmfOn?'#26384A':'#262624'):(isDmfOn?'#e7f2fd':'#FAFAF9'),'important');
            el.style.setProperty('background-image',isDmfOn?dmfOnBg:bg,'important');
            el.style.setProperty('background-size','auto','important');
