  function mutationTouchesCustomerSource(muts){
    try{
      for(var mi=0;mi<muts.length;mi++){
        var m=muts[mi];
        var t=m&&m.target;
        if(t&&t.nodeType===1){
          if(t.id==='tm-customer-source-button'||t.id==='tm-customer-source-button-wrap')return true;
          if(t.closest&&t.closest('#tm-customer-source-button,#tm-customer-source-button-wrap'))return true;
          if(t.closest&&t.closest('.tm-cu-topbar-source-wrap,.tm-cu-topbar-source'))continue;
        }
        var nodes=Array.from(m.addedNodes||[]).concat(Array.from(m.removedNodes||[]));
        for(var ni=0;ni<nodes.length;ni++){
          var n=nodes[ni];
          if(!n||n.nodeType!==1)continue;
          if(n.id==='tm-customer-source-button'||n.id==='tm-customer-source-button-wrap')return true;
          if(n.querySelector&&n.querySelector('#tm-customer-source-button,#tm-customer-source-button-wrap'))return true;
        }
      }
    }catch(_){}
    return false;
  }
  function scheduleCustomerUpdateSourceSync(delay){
    try{
      if(customerUpdateSourceSyncTimer)return;
      customerUpdateSourceSyncTimer=setTimeout(function(){
        customerUpdateSourceSyncTimer=0;
        hideForeignCustomerSourceButton();
        syncCustomerUpdateTopbarSource();
      },Math.max(50,Number(delay)||120));
    }catch(_){}
  }
  function ensureCustomerUpdateSourceWatcher(){
    try{
      if(customerUpdateSourceObserver||!document.body)return;
      customerUpdateSourceObserver=new MutationObserver(function(muts){
        if(!mutationTouchesCustomerSource(muts))return;
        scheduleCustomerUpdateSourceSync(120);
      });
      customerUpdateSourceObserver.observe(document.body,{childList:true,subtree:true});
      hideForeignCustomerSourceButton();
    }catch(_){}
  }
  function normalizeCustomerUpdateSourceKey(v){
    var s=__tmNormTxt(v||'').toLowerCase().replace(/ё/g,'е');
    s=s.replace(/[«»"'`]/g,' ');
    s=s.replace(/\b(листовка|партнер|партнер|партнёр|рк|источник|реклама)\b\s*[:№#-]?\s*/g,' ');
    s=s.replace(/\s+/g,' ').trim();
    return s;
  }
  function customerUpdateSourceKind(v){
    var s=__tmNormTxt(v||'').toLowerCase().replace(/ё/g,'е');
    if(/партн/.test(s))return 'partner';
    if(/лист|рк|реклам|источ/.test(s))return 'rk';
    return '';
  }
  function customerUpdateSourceKeysMatch(a,b){
    var aa=normalizeCustomerUpdateSourceKey(a);
    var bb=normalizeCustomerUpdateSourceKey(b);
    if(!aa||!bb)return false;
    var an=(aa.match(/\d+/)||[''])[0].replace(/^0+(?=\d)/,'');
    var bn=(bb.match(/\d+/)||[''])[0].replace(/^0+(?=\d)/,'');
    if(an&&bn&&an===bn)return true;
    if(aa===bb)return true;
    if(aa.length>=6&&bb.indexOf(aa)!==-1)return true;
    if(bb.length>=6&&aa.indexOf(bb)!==-1)return true;
    return false;
  }
  function readCustomerUpdateSourceTone(sourceText){
    try{
      sourceText=String(sourceText||'').trim();
      if(!sourceText)return 'gray';
      var tbl=document.querySelector('#customer-requests-grid table.table, #customer-requests-grid table');
      var tb=tbl&&tbl.querySelector('tbody');
      if(!tbl||!tb)return 'gray';
      var ths=Array.from(tbl.querySelectorAll('thead th'));
      function headIdx(rx){
        for(var i=0;i<ths.length;i++){
          var t=__tmNormTxt(ths[i].textContent||'').toLowerCase();
          if(rx.test(t))return i;
        }
        return -1;
      }
      var statusIdx=headIdx(/^статус/i);
      var partnerIdx=headIdx(/^партнер|^партн/i);
      var rkIdx=headIdx(/^рк|^лист|листов|реклам|источ/i);
      var kind=customerUpdateSourceKind(sourceText);
      var activeRows=0;
      var matched=false;
      function cellText(row,i){
        if(i<0)return '';
        var c=row.cells&&row.cells[i];
        return __tmNormTxt((c&&c.textContent)||'');
      }
      Array.from(tb.querySelectorAll('tr')).forEach(function(row){
        if(matched)return;
        if(!row||row.classList.contains('empty'))return;
        var status=cellText(row,statusIdx).toLowerCase().replace(/ё/g,'е');
        if(!/(ожида|в\s*пути|в\s*работе)/i.test(status))return;
        activeRows++;
        var p=cellText(row,partnerIdx);
        var rk=cellText(row,rkIdx);
        if(kind==='partner'){
          if(customerUpdateSourceKeysMatch(sourceText,p))matched=true;
          return;
        }
        if(kind==='rk'){
          if(customerUpdateSourceKeysMatch(sourceText,rk))matched=true;
          return;
        }
        if(customerUpdateSourceKeysMatch(sourceText,p)||customerUpdateSourceKeysMatch(sourceText,rk))matched=true;
      });
      var tone=activeRows?(matched?'green':'red'):'gray';
      window.__tmCuSourceTone=tone;
      return tone;
    }catch(_){}
    return 'gray';
  }
  function syncCustomerUpdateTopbarSource(){
    try{
      var top=document.getElementById('tm-cu-topbar');
      if(!top)return;
      var sourceText=readCustomerUpdateSourceText();
      var old=top.querySelector('.tm-cu-topbar-source-wrap');
      hideForeignCustomerSourceButton();
      if(!sourceText){
        if(old)old.remove();
        return;
      }
      window.__tmCuSourceText=sourceText;
      var tone=readCustomerUpdateSourceTone(sourceText);
      var wrap=old;
      if(!wrap){
        wrap=document.createElement('div');
        wrap.className='tm-cu-topbar-source-wrap';
        var right=top.querySelector('.tm-cu-topbar-actions');
        top.insertBefore(wrap,right||null);
      }
      var source=wrap.querySelector('.tm-cu-topbar-source');
      if(!source){
        source=document.createElement('div');
        source.className='tm-cu-topbar-source';
        wrap.appendChild(source);
      }
      var nextTone='is-'+(tone||'gray');
      if(source.dataset.tmCuTone!==nextTone){
        source.classList.remove('is-green','is-red','is-gray');
        source.classList.add(nextTone);
        source.dataset.tmCuTone=nextTone;
      }
      if(source.dataset.tmCuText!==sourceText){
        source.textContent=sourceText;
        source.title=sourceText;
        source.dataset.tmCuText=sourceText;
      }
    }catch(_){}
  }
