        if(!head)return null;
        var active=head.querySelector('a .badge.badge-danger, .badge.badge-danger');
        if(active&&__tmNormTxt(active.textContent||'')){
          return {kind:'active',label:'У клиента активная претензия',raw:__tmNormTxt(active.textContent||'')};
        }
        var past=head.querySelector('.badge.badge-success');
        if(past&&__tmNormTxt(past.textContent||'')){
          return {kind:'past',label:'У клиента была претензия',raw:__tmNormTxt(past.textContent||'')};
        }
