    function initCustomerUpdateCitySuggest(group){
      try{
        if(!group)return;
        var sel=group.querySelector('select#customer-city_id,select[name="Customer[city_id]"],select.form-control');
        if(!sel||sel.dataset.tmCuCitySuggestBound==='1')return;
        sel.dataset.tmCuCitySuggestBound='1';
        var s2=group.querySelector('.select2,.select2-container');
        if(s2)s2.style.setProperty('display','none','important');
        sel.style.setProperty('display','none','important');

        var btn=group.querySelector('.tm-cu-city-btn');
        var txt=null;
        if(!btn){
          btn=document.createElement('button');
          btn.type='button';
          btn.className='trig tm-cu-city-btn';
          btn.style.width='100%';
          txt=document.createElement('span');
          txt.className='tv ph';
          txt.textContent='Выберите';
          var caret=document.createElement('i');
          caret.className='ti ti-chevron-down caret';
          btn.appendChild(txt);
          btn.appendChild(caret);
          group.appendChild(btn);
        }else{
          txt=btn.querySelector('.tv');
          if(!txt){
            txt=document.createElement('span');
            txt.className='tv ph';
            btn.insertBefore(txt,btn.firstChild||null);
          }
        }

        function norm(v){return String(v||'').replace(/\s+/g,' ').trim();}
        function comp(v){return norm(v).toLowerCase().replace(/ё/g,'е');}
        function words(v){return comp(v).split(/[\s\-–—()]+/).map(function(t){return t.trim();}).filter(Boolean);}
        function score(text,q,qt){
          if(!text||!q)return 0;
          if(text===q)return 3000;
          if(text.indexOf(q)===0)return 2500;
          var ww=words(text);
          if(!ww.length)return 0;
          if(ww.some(function(w){return w===q;}))return 2300;
          if(ww.some(function(w){return w.indexOf(q)===0;}))return 2000;
          if(qt.length>1){
            for(var i=0;i<=ww.length-qt.length;i++){
              var ok=true;
              for(var j=0;j<qt.length;j++){ if(ww[i+j].indexOf(qt[j])!==0){ ok=false; break; } }
              if(ok)return 1800;
            }
          }
          return 0;
        }
        function syncBtnLabel(){
          var opt=(sel.options&&sel.selectedIndex>=0)?sel.options[sel.selectedIndex]:null;
          var t=norm((opt&&opt.text)||'');
          if(!t||/^выберите/i.test(t)){txt.textContent='Выберите';txt.classList.add('ph');}
          else{txt.textContent=t;txt.classList.remove('ph');}
        }
        function getItems(q){
          var nq=comp(q);
          var qTokens=nq?nq.split(/[\s\-–—]+/).map(function(t){return t.trim();}).filter(Boolean):[];
          var out=[];
          for(var i=0;i<(sel.options?sel.options.length:0);i++){
            var o=sel.options[i];
            if(!o||!String(o.value||'').trim())continue;
            var t=norm(o.text||'');
            if(!t||/^выберите/i.test(t))continue;
            var c=comp(t);
            var sc=o.selected?50:0;
            if(!nq){
              sc+=(o.selected?1000:100);
            }else{
              var m=c.match(/^(.*?)\s*\(([^)]*)\)\s*$/);
              var main=m?m[1].trim():c;
              var br=m?m[2].trim():'';
              var sMain=score(main,nq,qTokens);
              var sBr=br?score(br,nq,qTokens):0;
              if(sMain>0)sc+=sMain;
              else if(sBr>0)sc+=sBr-700;
              else continue;
            }
            out.push({v:o.value,t:t,score:sc,idx:i});
          }
          out.sort(function(a,b){if(b.score!==a.score)return b.score-a.score;return a.idx-b.idx;});
          return nq?out.slice(0,80):out.slice(0,40);
        }

        var drop=null;
        var searchInput=null;
        function host(){
          var h=btn.closest('.f')||btn.parentElement;
          if(h&&window.getComputedStyle(h).position==='static')h.style.position='relative';
          return h||document.body;
        }
        function closeDrop(instant){
          btn.classList.remove('is-open');
          if(drop){
            var d=drop;drop=null;searchInput=null;
            if(instant){
              if(d.parentNode)d.remove();
              toggleDropdownCardByInput(btn,false);
            }else{
              animateDropdownClose(d,function(){
                if(d.parentNode)d.remove();
                toggleDropdownCardByInput(btn,false);
              });
            }
          }else{
            toggleDropdownCardByInput(btn,false);
          }
        }
        function renderList(items){
          if(!drop)return;
          var list=drop.querySelector('.city-drop-list');
          if(!list)return;
          list.innerHTML='';
          var cur=String(sel.value||'');
          if(!items.length){
            var empty=document.createElement('div');
            empty.className='tm-name-suggest-empty';
            empty.textContent='Ничего не найдено';
            list.appendChild(empty);
            return;
          }
          items.forEach(function(item){
            var rowBtn=document.createElement('button');
            rowBtn.type='button';
            rowBtn.className='tm-name-suggest-item';
            if(cur&&String(item.v)===cur)rowBtn.classList.add('is-selected');
            var tx=document.createElement('span');
            tx.className='tm-name-suggest-text';
            tx.textContent=item.t;
            rowBtn.appendChild(tx);
            rowBtn.addEventListener('mousedown',function(e){e.preventDefault();});
            rowBtn.addEventListener('click',function(){
              sel.value=item.v;
              sel.dispatchEvent(new Event('input',{bubbles:true}));
              sel.dispatchEvent(new Event('change',{bubbles:true}));
              sel.dispatchEvent(new Event('blur',{bubbles:true}));
              syncBtnLabel();
              closeDrop();
              if(isModerationOrClarificationStatusNow()){
                setTimeout(function(){try{warmupAppTypeAfterCitySelect();}catch(_w){}},0);
              }
            });
            list.appendChild(rowBtn);
          });
        }
        function openDrop(){
          requestSingleDropdownOpen(btn);
          closeDrop(true);
          btn.classList.add('is-open');
          drop=document.createElement('div');
          drop.className='tm-name-suggest-dropdown city-search-dropdown';
          drop.style.left='0';
          drop.style.top='100%';
          drop.style.marginTop='3px';
          drop.style.width='100%';
          drop.style.zIndex='10000010';
          var searchWrap=document.createElement('div');
          searchWrap.className='city-drop-search-wrap';
          searchInput=document.createElement('input');
          searchInput.type='text';
          searchInput.className='city-drop-search';
          searchInput.placeholder='Поиск города';
          searchInput.autocomplete='off';
          searchWrap.appendChild(searchInput);
          drop.appendChild(searchWrap);
          var list=document.createElement('div');
          list.className='city-drop-list';
          drop.appendChild(list);
          renderList(getItems(''));
          drop.dataset.noOpenAnim='1';
          host().appendChild(drop);
          toggleDropdownCardByInput(btn,true);
          delete drop.dataset.noOpenAnim;
          animateDropdownOpen(drop);
          setTimeout(function(){if(searchInput)searchInput.focus();},30);
          searchInput.addEventListener('input',function(){renderList(getItems(searchInput.value||''));});
          searchInput.addEventListener('keydown',function(e){
            if(e.key==='Escape'){closeDrop();btn.focus();return;}
            if(e.key==='Enter'){
              e.preventDefault();
              var first=drop&&drop.querySelector('.city-drop-list .tm-name-suggest-item');
              if(first)first.click();
            }
          });
        }
        bindSingleDropdownCloser(btn,function(){closeDrop(true);});
        btn.addEventListener('click',function(e){e.stopPropagation();if(drop)closeDrop();else openDrop();});
        document.addEventListener('pointerdown',function(e){
          if(!drop)return;
          if(e.target===btn||btn.contains(e.target))return;
          if(drop.contains(e.target))return;
          closeDrop();
        },true);
        sel.addEventListener('change',syncBtnLabel);
        syncBtnLabel();
      }catch(_){}
    }
